,p_plugin_type=>'DYNAMIC ACTION'
,p_name=>'COM.HARDSOFTSAS.MENU_SEARCH'
,p_display_name=>'APEX Side Navigation Smart Search'
,p_apexlang_name=>'apexSideNavigationSmartSearch'
,p_category=>'NAVIGATION'
,p_image_prefix=>nvl(wwv_flow_application_install.get_static_plugin_file_prefix('DYNAMIC ACTION','COM.HARDSOFTSAS.MENU_SEARCH'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION render_menu_search (',
'    p_dynamic_action IN apex_plugin.t_dynamic_action,',
'    p_plugin         IN apex_plugin.t_plugin ',
') RETURN apex_plugin.t_dynamic_action_render_result ',
'IS',
'    l_result apex_plugin.t_dynamic_action_render_result;',
'BEGIN',
'    -- 1. Cargar el archivo CSS',
'    apex_css.add_file(',
unistr('        p_name      => ''menu_search'', -- Nombre sin extensi\00F3n'),
'        p_directory => p_plugin.file_prefix',
'    );',
'',
'    -- 2. Cargar el archivo JS',
'    apex_javascript.add_library(',
unistr('        p_name      => ''menu_search'', -- Nombre sin extensi\00F3n'),
'        p_directory => p_plugin.file_prefix',
'    );',
'',
unistr('    -- 3. Definir qu\00E9 ejecuta la Acci\00F3n Din\00E1mica'),
unistr('    -- Como tu JS usa una funci\00F3n autoejecutable $(function() {...}) para inyectarse,'),
unistr('    -- aqu\00ED solo necesitamos retornar una funci\00F3n vac\00EDa o un log para cumplir el contrato.'),
'    l_result.javascript_function := ''function(){ console.log("Search Plugin Loaded"); }'';',
'',
'    RETURN l_result;',
'END render_menu_search;'))
,p_api_version=>1
,p_render_function=>'render_menu_search'
,p_substitute_attributes=>true
,p_version_scn=>'SH256:L5j3W8f4_Rf-lOcXiF1Vm9M4VtcS6yZHm4KRcXMj1kM'
,p_version_identifier=>'1.0'
