prompt --application/shared_components/navigation/lists/card_as_list_template
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(7655603165809138465)
,p_name=>'Card as list template'
,p_static_id=>'card-as-list-template'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    m.meeting_id                         AS card_id,',
'',
'    e.first_name || '' '' || e.last_name   AS card_title,',
'',
'    m.meeting_title                      AS card_subtitle,',
'',
'    ''https://g64cf2f956d7752-playground01.adb.us-ashburn-1.oraclecloudapps.com/ords/dev_tavish1/fetch/'' ',
'    || e.id                              AS card_image,',
'',
'    ''Email: '' || e.email_id || ''<br>'' ||',
'    ''Birth Date: '' || TO_CHAR(e.birth_date,''DD-MON-YYYY'') || ''<br>'' ||',
'    ''Gender: '' || e.gender || ''<br>'' ||',
'    ''Address: '' || DBMS_LOB.SUBSTR(e.address, 200, 1) || ''<br><br>'' ||',
'',
'    ''<b>Meeting Details</b><br>'' ||',
'    ''Title: '' || m.meeting_title || ''<br>'' ||',
'    ''Start: '' || TO_CHAR(m.start_datetime,''DD-MON-YYYY HH24:MI'') || ''<br>'' ||',
'    ''Type: '' || m.meeting_type || ''<br>'' ||',
'    ''Location: '' || m.meeting_location || ''<br>'' ||',
'    ''Status: '' || m.status               AS card_text,',
'',
'    CASE',
'        WHEN m.status = ''SCHEDULED'' THEN ''u-color-37''',
'        WHEN m.status = ''COMPLETED'' THEN ''u-color-34''',
'        WHEN m.status = ''CANCELLED'' THEN ''u-color-39''',
'        ELSE ''u-color-45''',
'    END AS card_css_class',
'',
'FROM ta_meetings m',
'JOIN ta_emp e',
'  ON e.id = m.organizer_id;',
''))
,p_version_scn=>'46137164166084'
);
end;
/
