prompt --application/shared_components/logic/application_processes/login_user_log
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(13443965402220491180)
,p_process_sequence=>1
,p_process_point=>'AFTER_LOGIN'
,p_process_name=>'LOGIN_USER_LOG'
,p_static_id=>'login-user-log'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_user_agent VARCHAR2(500);',
'',
'    v_device VARCHAR2(255);',
'    v_browser VARCHAR2(255);',
'BEGIN',
'    v_user_agent := OWA_UTIL.GET_CGI_ENV(''HTTP_USER_AGENT'');',
'',
'    v_device := CASE ',
'                    WHEN lower(v_user_agent) LIKE ''%mobile%'' THEN ''Mobile''',
'                    WHEN lower(v_user_agent) LIKE ''%tablet%'' THEN ''Tablet''',
'                    ELSE ''Desktop''',
'                END;',
'',
'    v_browser := CASE ',
'                    WHEN v_user_agent LIKE ''%Firefox%'' THEN ''Mozilla Firefox''',
'                    WHEN v_user_agent LIKE ''%Edg%'' THEN ''Microsoft Edge''',
'                    WHEN v_user_agent LIKE ''%Chrome%'' THEN ''Google Chrome''',
'                    WHEN v_user_agent LIKE ''%Safari%'' AND v_user_agent NOT LIKE ''%Chrome%'' THEN ''Safari''',
'                    ELSE ''Other''',
'                END;',
'',
'    INSERT INTO TA_USER_ACTIVITY_LOGS (',
'        USER_ID, ',
'        USER_NAME, ',
'        SESSION_ID, ',
'        IP_ADDRESS,',
'        LOGIN_TIME,',
'        APP_ID,',
'        USER_AGENT,',
'        DEVICE_TYPE,',
'        BROWSER',
'    ) VALUES (',
'        :APP_USER_ID, ',
'        :APP_USER, ',
'        :APP_SESSION, ',
'        sys_context(''USERENV'', ''IP_ADDRESS''),',
'        get_ist_systimestamp,',
'        :APP_ID,',
'        v_user_agent,',
'        v_device,',
'        v_browser',
'    );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'SH256:ui-zujN4z3EKYgmW36oNMj4N6K1Ka57Pb1Zk1V4Bg2A'
,p_created_on=>wwv_flow_imp.dz('20260630094710Z')
,p_updated_on=>wwv_flow_imp.dz('20260630094846Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
