,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13723547313088243019)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Redirect to other page '
,p_static_id=>'redirect-to-other-page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_home_page  NUMBER;',
'  l_page_alias VARCHAR2(255);',
'BEGIN',
'-- Get home page of login user',
'  BEGIN',
'    SELECT APEX_PAGE_ID INTO l_home_page FROM TA_DAYWISE_NAVIGATION_MENU_MASTER',
'    WHERE APEX_PAGE_ID IS NOT NULL',
'    ORDER BY MENU_SEQ_ID ',
'    FETCH FIRST 1 ROW ONLY ;',
'  exception',
'  WHEN others THEN',
'    l_home_page := 1; -- login page',
'  END;',
'  ',
'-- Get page alias from apex view [To construct secured URL, we need page alias instead of page id]  ',
'  BEGIN',
'    SELECT LOWER(page_alias)',
'    INTO l_page_alias',
'    FROM apex_application_pages',
'    WHERE application_id = :APP_ID         -- v(''APP_ID'')      ',
'    AND page_id = l_home_page;',
'  exception',
'  WHEN others THEN',
'    l_page_alias := l_home_page;',
'  END;',
'  ',
