,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="u-textCenter apex-arch-diagram">',
'  <img src="https://g64cf2f956d7752-playground01.adb.us-ashburn-1.oraclecloudapps.com/ords/dev_tavish1/image/get?IMAGE_STATIC_ID=APEX_ARCHITECTURE"',
'       alt="Oracle APEX Architecture Diagram">',
'',
'  <div class="apex-lists">',
'    <div class="list">',
'        <h3> GET </h3>',
'    <ol class="get-list">',
'      <li>User clicks a link which sends HTTPS GET request to ORDS</li>',
'      <li>ORDS makes a database JDBC call to the APEX Engine</li>',
'      <li>APEX generates HTML page (full page or partial)</li>',
'      <li>ORDS returns the generated HTML back to the browser</li>',
'    </ol>',
'    </div>',
'    <div class="list">',
'        <h3> POST </h3>',
'    <ol class="post-list">',
'      <li>User clicks a button which does an HTTP POST to ORDS</li>',
'      <li>ORDS makes a database JDBC call to the APEX Engine</li>',
'      <li>APEX processes the request</li>',
'      <li>APEX determines URL and branches</li>',
'    </ol>',
'    </div>',
'  </div>',
'</div>',
'',
'<style>',
'.apex-arch-diagram img {',
'  max-width: 100%;',
