wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(7651567674960375737)
,p_name=>'On-Premises vs Cloud'
,p_static_id=>'on-premises-vs-cloud'
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- SELECT ',
'--     ''ROW1-C1'' AS COL1,',
'--     ''ROW1-C2'' AS COL2,',
'--     ''ROW1-C3'' AS COL3',
'-- FROM DUAL',
'-- UNION ALL',
'-- SELECT ',
'--     ''ROW2-C1'' AS COL1,',
'--     ''ROW2-C2'' AS COL2,',
'--     ''ROW2-C3'' AS COL3',
'-- FROM DUAL',
'',
'select ',
'    ''<b>'' || Aspect || ''</b>'' as Aspect,',
'    On_Premises_APEX,',
'    Cloud_APEX_OCI_Autonomous,',
'    seq',
'from(',
'    SELECT ',
'        ''Hosting'' as Aspect,',
'        ''Companys own servers'' as On_Premises_APEX,',
'        ''Oracle Cloud Infrastructure'' as Cloud_APEX_OCI_Autonomous,',
'        1 as seq',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Database Management'',',
'        ''Manual (DBA required)'',',
'        ''Fully managed by Oracle'',',
'        2',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Installation'',',
'        ''Manual setup of DB, APEX, ORDS, Web Server'',',
'        ''Pre-configured'',',
'        3',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Upgrades'',',
'        ''Manual APEX & DB upgrades'',',
'        ''Automatic / one-click'',',
'        4',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Scalability'',',
'        ''Limited by hardware'',',
'        ''Auto-scaling'',',
'        5',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Performance'',',
'        ''Depends on hardware'',',
'        ''Optimized & elastic'',',
'        6',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Security'',',
'        ''Fully controlled by organization'',',
'        ''Oracle-managed, enterprise-grade'',',
'        7',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Cost Model'',',
'        ''High upfront (hardware + licenses)'',',
'        ''Pay-as-you-go'',',
'        8',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Maintenance Effort'',',
'        ''High'',',
'        ''Very low'',',
'        9',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Availability'',',
'        ''Depends on infra setup'',',
'        ''High availability built-in'',',
'        10',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''AI Features'',',
'        ''Limited / manual setup'',',
'        ''Built-in AI, RAG, GenAI'',',
'        11',
'    FROM DUAL',
')',
'order by seq'))
,p_header=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!-- <strong><h3> Oracle APEX: On-Premises vs Cloud</h3></strong> -->',
'<p>Oracle APEX can be deployed <strong>on-premises</strong> (your own infrastructure) or in the cloud (Oracle Cloud Infrastructure or Autonomous Database). <br>',
'The core APEX features are the same, but <strong>deployment, management, cost, and scalability differ.</strong></p>'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
