wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7651568535243375746)
,p_plug_name=>'Oracle APEX Cloud (OCI/Autonomous)'
,p_static_id=>'oracle-apex-cloud-oci-autonomous'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:t-Region--controlsPosEnd:is-expanded:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li> <strong> Pros: </strong> Lower TCO, no hardware to purchase, Automatic scaling based on demand. Autonomous Database provides self-driving, self-securing, and self-repairing capabilities.</li>',
'    <li> <strong> Cons: </strong> Dependence on internet connectivity and cloud provider, potential data sovereignty concerns for certain industries.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7651568486256375745)
,p_plug_name=>'Oracle APEX On-Premises'
,p_static_id=>'oracle-apex-on-premises'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:t-Region--controlsPosEnd:is-expanded:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li> <strong> Pros: </strong> Total control over data residency, security, and OS/Database versioning. Ideal if you have strict compliance, data sovereignty requirements, or existing on-prem systems that require low-latency integration.</li>',
'    <li> <strong> Cons: </strong> High upfront investment (hardware, licenses), higher Total Cost of Ownership (TCO), and responsibility for managing backups, performance tuning, and patching.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
