,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>This shows the <strong>Oracle APEX App Builder \2013 Dashboard.</strong> Here\2019s a clear overview of what\2019s going on</p>'),
'<p><h4><strong>Top Summary Numbers</strong></h4></p>',
'<ul>',
'    <li><strong>Applications:</strong> Total number of APEX applications in the workspace.</li>',
'    <li><strong>Pages:</strong> Total pages across all applications.</li>',
'</ul>',
'<p><h4><strong>Developer Activity</strong></h4></p>',
'<ul>',
'    <li>Displays which developers were active recently.</li>',
'    <li>Helps identify <strong>who is working most in the workspace.</strong></li>',
'</ul>',
'<p><h4><strong>Page Events</strong></h4></p>',
'<ul>',
'    <li>Shows <strong>page activity over time</strong> (events like page views, edits, runs).</li>',
'    <li>Spikes indicate <strong>busy development or testing periods.</strong></li>',
'</ul>',
'<p><h4><strong>Page Count by Application</strong></h4></p>',
'<ul>',
'    <li>Horizontal bar chart listing applications with their <strong>page counts.</strong></li>',
'    <li>Helps identify:',
'        <ol>',
'            <li>Large applications</li>',
'            <li>Smaller or Demo applications</li>',
'        </ol>',
'    </li>',
'</ul>',
'<p><h4><strong>Most Active Pages</strong></h4></p>',
'<ul>',
'    <li>Bar chart showing <strong>which pages are accessed the most.</strong></li>',
'    <li>Higher bars = frequently used pages.</li>',
'</ul>',
'<p><h4><strong>Native Region Component Utilization</strong></h4></p>',
'<ul>',
'    <li>Bottom chart showing usage of APEX components like: ',
'        <ol>',
'            <li>Static Content</li>',
'            <li>Interactive Report</li>',
'            <li>Classic Report</li>',
'            <li>Forms, Lists, Charts, etc.</li>',
'        </ol>',
'    </li>',
'    <li>Helps understand:',
'        <ol>',
'            <li>Which components are used heavily</li>',
'            <li>Design patterns followed in the workspace</li>',
'        </ol>',
'    </li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
