wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7661645423202139355)
,p_plug_name=>'Instructions'
,p_static_id=>'instructions'
,p_parent_plug_id=>wwv_flow_imp.id(7661645349584139354)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>On the Workspace home page, click <strong>SQL Workshop.</strong></li>',
'    <li>Click <strong>Object Browser.</strong></li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7661645793790139358)
,p_plug_name=>'Instructions'
,p_static_id=>'instructions-2'
,p_parent_plug_id=>wwv_flow_imp.id(7661645634753139357)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_grid_column_span=>7
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Object Browser is divided into teo panes:</p>',
'<ul>',
'    <li><strong>Object Tree -</strong> The Object Tree displays database objects of a selected type within the current schema. To view specific objects, expand the object type and select the object in the tree.</li>',
'    <li><strong>Object Detail View -</strong> Selecting an object type in the Object Tree populates the Object Detail View. The Object Detail View displays tabs specific to the object type. Each tab displays actions appropriate for the object.</li>',
'</ul>',
'<p><strong>About the Object Tree Context Menus</strong></p>',
'<ul>',
'    <li><strong>Create</strong> Launches the appropriate Create Object dialog.</li>',
'    <li><strong>Refresh</strong> Refreshes the current view.</li>',
'    <li><strong>Expand All</strong> Expands all nodes in the Object Tree.</li>',
'    <li><strong>Collapse All</strong> Collapses all nodes in the Object Tree.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662355505023076018)
,p_plug_name=>'Instructions'
,p_static_id=>'instructions-3'
,p_parent_plug_id=>wwv_flow_imp.id(7662355141415076015)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_grid_column_span=>7
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>'<p>Filter objects by entering a search term in the filter above the Object Tree.</p>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662355690787076020)
,p_plug_name=>'Instructions'
,p_static_id=>'instructions-4'
,p_parent_plug_id=>wwv_flow_imp.id(7662355579605076019)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Learn about the Code Editor available Object Browser.</p>',
'<p>Many tabs in Object Detail View feature a fully functional Code Editor. The following example shows the <strong>DDL</strong> tab for the DEPT table.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7661646093157139361)
,p_plug_name=>'Object Detail View'
,p_static_id=>'object-detail-view'
,p_parent_plug_id=>wwv_flow_imp.id(7661645911997139360)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>In Object Browser, expand an object type in the Object Tree and select an object. The object details (also called the Object Detail View) appears.</p>',
'<ul>',
'    <li>The specific tabs available varies depending upon the object type. In the previous example, the DEPT table is selected and includes the following tabs:',
'        <ul>',
'            <li><strong>Columns</strong></li>',
'            <li><strong>Data</strong></li>',
'            <li><strong>Indexes</strong></li>',
'            <li><strong>Constraints</strong></li>',
'            <li><strong>Grants</strong></li>',
'            <li><strong>Statistics</strong></li>',
'            <li><strong>Triggers</strong></li>',
'            <li><strong>Dependencies</strong></li>',
'            <li><strong>DDL</strong></li>',
'            <li><strong>Sample Queries</strong></li>',
'        </ul>',
'    </li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662354913531076013)
,p_plug_name=>'Object Tabs and Actions'
,p_static_id=>'object-tabs-and-actions'
,p_parent_plug_id=>wwv_flow_imp.id(7661645911997139360)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>You can view and edit the table data using the <strong>Data</strong> tab.</p>',
'<ul>',
'    <li>The Data tab includes the following Actions:',
'        <ul>',
'            <li><strong>Insert Row</strong></li>',
'            <li><strong>Columns</strong></li>',
'            <li><strong>Filter</strong></li>',
'            <li><strong>Count Rows</strong></li>',
'            <li><strong>Load Data</strong></li>',
'            <li><strong>Download</strong></li>',
'            <li><strong>Refresh</strong></li>',
'        </ul>',
'    </li>',
'    <li>Click the <strong>Data</strong> tab.</li>',
'    <li>Click the <strong>Insert Row</strong> action. Clicking an action displays a dialog box.</li>',
'    <li>Edit the row details and click <strong>Create.</strong></li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7661645634753139357)
,p_plug_name=>'Object Tree and Object Detail View'
,p_static_id=>'object-tree-and-object-detail-view'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7661645290170139353)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Object Browser enables developers to browse, create, and edit objects in the Oracle Database.</p>',
'<p>Oracle APEX has many views defined to help you work with the underlying table structures. The views combine multiple base tables and use meaningful column names to minimize complexity and to be more intuitive to use.</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7661645911997139360)
,p_plug_name=>'Selecting Objects and Viewing Object Details'
,p_static_id=>'selecting-objects-and-viewing-object-details'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
