,p_autocomplete_on_off=>'OFF'
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'11'
,p_last_updated_on=>wwv_flow_imp.dz('20260701101553Z')
,p_last_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662355872850076022)
,p_plug_name=>'About SQL Commands'
,p_static_id=>'about-sql-commands'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>You can use SQL Commands to create, edit, view, run, and delete database objects.</p>',
'<p>A SQL command can contain SQL statements or PL/SQL blocks.</p>',
'<p>When using SQL Commands, remember the following:',
'    <ul>',
'        <li>SQL commands created in the Query Builder can be accessed from SQL Commands.</li>',
'        <li>Saved SQL commands must have unique names within a given workspace.</li>',
'        <li>There is no interaction between SQL Commands and SQL Scripts.</li>',
'        <li>You can cut and paste an SQL command from SQL Commands to run in the SQL Script Editor.</li>',
'    </ul>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
