,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>From the Workspace home page, go to <strong>SQL Workshop -> SQL Scripts.</strong></li>',
'    <li>Click <strong>Create</strong> to open the Script Editor.</li>',
'    <li>Enter a <strong>Script Name</strong></li>',
'    <li>Add your SQL statements or PL/SQL blocks.</li>',
'    <li>Click <strong>Create.</strong></li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
