wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662357970520076043)
,p_plug_name=>'Creating an Application from a Script'
,p_static_id=>'creating-an-application-from-a-script'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>80
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p><strong>Required</strong><br><br>The tables specified in the script must exist in your workspace to use the Create App button. Run the script or load the tables first.</p>',
'<p><strong>Procedure</strong></p>',
'<ol>',
'    <li>In SQL Workshop, click <strong>SQL Scripts.</strong></li>',
'    <li>Click the <strong>Edit</strong> icon for the script.</li>',
'    <li>Do one of the following:</strong>',
'        <ul>',
'            <li>Click <strong>Create App.</strong></li>',
'            <li>Run the Script and click <strong>Create App.</strong></li>',
'        </ul>',
'    </li>',
'    <li>Click <strong>Create Application</strong> on the confirmation dialog.</li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
