,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>On the Workspace home page, click <strong>SQL Workshop</strong> and then <strong>SQL Scripts.</strong></li>',
'    <li>On the Tasks list, click <strong>Export.</strong></li>',
'    <li>Under Scripts:',
'        <ul>',
'            <li>Select the Scripts you want to export. To select all displayed scripts, click the column head check box.</li>',
'            <li>Click <strong>Add to Export.</strong></li>',
'            <li>The selected scripts display under <strong>Scripts to Export.</strong></li>',
'        </ul>',
'    </li>',
'    <li>Under <strong>Scripts to Export:</strong>',
'        <ul>',
'            <li><strong>File Name -</strong> Enter a name for the export script.</li>',
'            <li>To remove a script, deselect it and click <strong>Remove Checked.</strong></li>',
'            <li>Click <strong>Export All.</strong></li>',
'        </ul>',
'    </li>',
'    <li>Import the Script Export.</li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
