wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7655555686785983849)
,p_plug_name=>'Template Options'
,p_static_id=>'template-options'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>100
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="apex-template-options">',
'',
'  <h2 class="main-title">Template Options</h2>',
'',
'  <!-- General -->',
'  <div class="row">',
'    <div class="left">',
'      <div class="title">General</div>',
'    </div>',
'    <div class="right">',
'      <div class="option">',
'        <input type="checkbox" checked>',
'        <label>Use Template Defaults</label>',
'      </div>',
'      <div class="option">',
'        <input type="checkbox">',
'        <label>Highlight Background</label>',
'        <div class="desc">',
'          Set alert background color to that of the alert type (warning, success, etc.)',
'        </div>',
'      </div>',
'    </div>',
'  </div>',
'',
'  <!-- Alert Display -->',
'  <div class="row">',
'    <div class="left">',
'      <div class="title">Alert Display</div>',
'      <div class="subtitle">Sets the layout of the Alert Region.</div>',
'    </div>',
'    <div class="right">',
'      <div class="option">',
'        <input type="radio" name="display" checked>',
'        <label>Horizontal</label>',
'        <div class="desc">Show horizontal alert with buttons to the right.</div>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="display">',
'        <label>Wizard</label>',
'        <div class="desc">Show the alert in a wizard style region.</div>',
'      </div>',
'    </div>',
'  </div>',
'',
'  <!-- Alert Icons -->',
'  <div class="row">',
'    <div class="left">',
'      <div class="title">Alert Icons</div>',
'      <div class="subtitle">Sets how icons are handled for the Alert Region.</div>',
'    </div>',
'    <div class="right">',
'      <div class="option">',
'        <input type="radio" name="icons">',
'        <label>Hide Icons</label>',
'        <div class="desc">Hides alert icons.</div>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="icons" checked>',
'        <label>Show Default Icons</label>',
'        <div class="desc">Uses default icons for alert types.</div>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="icons">',
'        <label>Show Custom Icons</label>',
'        <div class="desc">',
'          Set custom icons by modifying the Alert Region''s Icon CSS Classes property.',
'        </div>',
'      </div>',
'    </div>',
'  </div>',
'',
'  <!-- Alert Type -->',
'  <div class="row">',
'    <div class="left">',
'      <div class="title">Alert Type</div>',
'      <div class="subtitle">',
'        Sets the type of alert which can be used to determine the icon, icon color, and the background color.',
'      </div>',
'    </div>',
'    <div class="right">',
'      <div class="option">',
'        <input type="radio" name="atype" checked>',
'        <label>Warning</label>',
'        <div class="desc">Show a warning alert.</div>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="atype">',
'        <label>Danger</label>',
'        <div class="desc">Show an error or danger alert.</div>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="atype">',
'        <label>Information</label>',
'        <div class="desc">Show informational alert.</div>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="atype">',
'        <label>Success</label>',
'        <div class="desc">Show success alert.</div>',
'      </div>',
'    </div>',
'  </div>',
'',
'  <!-- Alert Title -->',
'  <div class="row">',
'    <div class="left">',
'      <div class="title">Alert Title</div>',
'      <div class="subtitle">Determines how the title of the alert is displayed.</div>',
'    </div>',
'    <div class="right">',
'      <div class="option">',
'        <input type="radio" name="atitle" checked>',
'        <label>Visible - Default</label>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="atitle">',
'        <label>Hidden</label>',
'        <div class="desc">Hides the Alert Title from being displayed.</div>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="atitle">',
'        <label>Hidden but Accessible</label>',
'        <div class="desc">',
'          Visually hides the alert title, but assistive technologies can still read it.',
'        </div>',
'      </div>',
'    </div>',
'  </div>',
'',
'  <!-- Item Padding -->',
'  <div class="row">',
'    <div class="left">',
'        <span class="badge">ADVANCED</span>',
'      <div class="title">Item Padding</div>',
'      <div class="subtitle">Sets the padding around items within this region.</div>',
'    </div>',
'    <div class="right">',
'      <div class="option">',
'        <input type="radio" name="padding" checked>',
'        <label>Default</label>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="padding">',
'        <label>Slim Padding</label>',
'        <div class="desc">Reduces form item padding to 4px.</div>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="padding">',
'        <label>Remove Padding</label>',
'        <div class="desc">Removes padding between items.</div>',
'      </div>',
'    </div>',
'  </div>',
'',
'  <!-- Item Size -->',
'  <div class="row">',
'    <div class="left">',
'        <span class="badge">ADVANCED</span>',
'      <div class="title">Item Size</div>',
'      <div class="subtitle">Sets the size of the form items within this region.</div>',
'    </div>',
'    <div class="right">',
'      <div class="option">',
'        <input type="radio" name="size" checked>',
'        <label>Default</label>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="size">',
'        <label>Large</label>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="size">',
'        <label>X Large</label>',
'      </div>',
'    </div>',
'  </div>',
'',
'  <!-- Item Width -->',
'  <div class="row">',
'    <div class="left">',
'        <span class="badge">ADVANCED</span>',
'      <div class="title">Item Width</div>',
'      <div class="subtitle">Sets the width of the form items within this region.</div>',
'    </div>',
'    <div class="right">',
'      <div class="option">',
'        <input type="radio" name="width" checked>',
'        <label>Default</label>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="width">',
'        <label>Stretch Form Fields</label>',
'      </div>',
'    </div>',
'  </div>',
'',
'    <!-- Label Alignment -->',
'  <div class="row">',
'    <div class="left">',
'      <span class="badge">ADVANCED</span>',
'      <div class="title">Label Alignment</div>',
'      <div class="subtitle">',
'        Set the label text alignment for items within this region.',
'      </div>',
'    </div>',
'    <div class="right">',
'      <div class="option">',
'        <input type="radio" name="label_align" checked>',
'        <label>Right</label>',
'      </div>',
'      <div class="option">',
'        <input type="radio" name="label_align">',
'        <label>Left</label>',
'        <div class="desc">Align form labels to left.</div>',
'      </div>',
'    </div>',
'  </div>',
'',
'  <!-- Label Position -->',
'  <div class="row">',
'    <div class="left">',
'      <span class="badge">ADVANCED</span>',
