,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li><strong>Access the App Builder:</strong> From the workspace home page, click the <strong>App Builder</strong> icon and then select <strong>Create.</strong></li>',
'    <li><strong>Choose a Creation Method:</strong> You have several options for how to start your application:',
'        <ul>',
'            <li><strong>Blank Application:</strong> Start from blank slate and manually add pages later.</li>',
'        </ul>',
'    </li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7655374557059106934)
,p_plug_name=>'Key Development Tools'
,p_static_id=>'key-development-tools'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_grid_column_span=>5
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li><strong>App Builder:</strong> The primary integrated development environment (IDE) for designing pages and components.</li>',
'    <li><strong>Page Designer:</strong> A powerful interface with a layout editor, component tree, and property editor for detailed page customization using drag-and-drop functionality.</li>',
'    <li><strong>SQL Workshop:</strong> Used to create and maintain underlying database objects like tables, views, and PL/SQL code.</li>',
'    <li><strong>Team Developmement:</strong> Built-in tools for tracking tasks, bugs, and features across a development team.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7655374341755106932)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody:margin-bottom-md'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>'<p>Creating an application in Oracle APEX is <strong>a low-code, metadata-driven process performed within a web browser, primarily using the App Builder.</strong></p>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
