,p_plug_display_column=>8
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4 style="text-decoration:underline">Example of Application Item</h4>',
'',
'<p>',
'For example, create an Application Item named <strong>LAST_VIEW</strong>. You can store and use this value across the application.',
'</p>',
'',
'<p><strong>PL/SQL Process:</strong></p>',
'',
'<pre>',
':LAST_VIEW := :APP_PAGE_ID;',
'</pre>',
'',
'<p><strong>HTML Region:</strong></p>',
'',
'<pre>',
'Last visited page: &amp;LAST_VIEW.',
'</pre>',
'',
'<p><strong>SQL Query:</strong></p>',
'',
'<pre>',
'select *',
'from tasks',
'where page_id = :LAST_VIEW;',
'</pre>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
