 p_id=>wwv_flow_imp.id(7657024693701981929)
,p_plug_name=>'Creating an Application Computation'
,p_static_id=>'creating-an-application-computation'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Create an application computation from Shared Components.</p>',
'',
'<p><strong>To create an application computation:</strong></p>',
'',
'<ol>',
'',
'    <li>',
'        Navigate to the <strong>Shared Components</strong> page:',
'        <ul>',
'            <li>',
'                On the Workspace home page, click <strong>App Builder</strong>.',
'            </li>',
'            <li>',
'                Select an <strong>application</strong>.',
'            </li>',
'            <li>',
'                On the Application home page, click <strong>Shared Components</strong>.',
'            </li>',
'            <li>',
'                The <strong>Shared Components</strong> page appears.',
'            </li>',
'        </ul>',
'    </li>',
'',
'    <li>',
'        Under <strong>Application Logic</strong>, select ',
'        <strong>Application Computations</strong>.',
'    </li>',
'',
'    <li>',
'        Click <strong>Create</strong>.',
'    </li>',
'',
'    <li>',
'        Edit the following attributes:',
'        <ul>',
'            <li>',
'                <strong>Item, Sequence</strong> - Specify the sequence for this component. ',
'                The sequence determines the order of evaluation.',
'            </li>',
'            <li>',
'                <strong>Item, Computation Item</strong> - Select the item this computation affects.',
'            </li>',
'            <li>',
'                <strong>Frequency, Computation Point</strong> - Select a process point at which ',
'                this computation should be performed. Selecting <strong>After Submit</strong> ',
'                causes the computation to be performed only after the page is displayed and then submitted.',
'            </li>',
'        </ul>',
'    </li>',
'',
'</ol>',
'',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
