,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p><strong>Let''s examine the attributes in more detail:</strong></p>',
'',
'<ul>',
'',
'    <li>',
'        <strong>Name</strong>',
'        <ul>',
'            <li>',
'                The name for the Application Setting.',
'            </li>',
'            <li>',
'                This name is also used when referencing an Application Setting ',
'                from the PL/SQL APIs.',
'            </li>',
'        </ul>',
'    </li>',
'',
'    <li>',
'        <strong>Value</strong>',
'        <ul>',
'            <li>',
'                The current value for the Application Setting.',
'            </li>',
'            <li>',
'                This can be anything you want.',
'            </li>',
'        </ul>',
'    </li>',
'',
'    <li>',
'        <strong>Value Required</strong>',
'        <ul>',
'            <li>',
'                Determines if a value is required for the Application Setting.',
'            </li>',
'        </ul>',
'    </li>',
'',
'    <li>',
'        <strong>Valid Values</strong>',
'        <ul>',
'            <li>',
'                A comma-separated list of allowed values for the Application Setting.',
'            </li>',
'            <li>',
'                These values are enforced by the UI and by the PL/SQL APIs.',
'            </li>',
'            <li>',
'                If this attribute is left empty then validation is not performed.',
'            </li>',
'        </ul>',
'    </li>',
'',
'    <li>',
'        <strong>On Upgrade Keep</strong>',
'        <ul>',
'            <li>',
'                See the section <strong>''What Happens During Deployment''</strong> ',
'                for details on this attribute.',
'            </li>',
'        </ul>',
'    </li>',
'',
'</ul>',
''))
