 p_id=>wwv_flow_imp.id(7657025992395981942)
,p_plug_name=>'Session Management'
,p_static_id=>'session-management'
,p_parent_plug_id=>wwv_flow_imp.id(7662359120566076055)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody:margin-top-md'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>50
