,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Session Management is used to control how long a user session remains active in the Oracle APEX application. A session starts when a user logs in and ends when the user logs out or when the session times out.',
'</p>',
'',
'<h4>Why Session Management is Used</h4>',
'',
'<ul>',
'    <li>To protect the application from unauthorized access.</li>',
'    <li>To automatically log out inactive users.</li>',
'    <li>To improve application security.</li>',
'    <li>To manage user sessions efficiently.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
