wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930003620645843603)
,p_plug_name=>'Builder Extension Sign-In'
,p_static_id=>'builder-extension-sign-in'
,p_parent_plug_id=>wwv_flow_imp.id(17930003534850843602)
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4> What is it?</h4>',
'<p>This authentication is mainly used for <strong>Oracle APEX Builder Extensions</strong> and development tools. It authenticates users through the APEX Builder environment.</p>',
'<h4> Use Case </h4>',
'<ul>',
'    <li>Development</li>',
'    <li>Builder extenions</li>',
'    <li>Internal Oracle APEX tools</li>',
'</ul>',
'<h4>Example</h4>',
'<p>If you''re creating an extension that works inside Oracle APEX Builder.</p>',
'<h4>Advantages</h4>',
'<ul>',
'    <li>Easy for Builder extensions</li>',
'    <li>No extra configuration</li>',
'</ul>',
'<h4>Disadvantages</h4>',
'<ul>',
'    <li>Not used for normal business applications</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260715074449Z')
,p_updated_on=>wwv_flow_imp.dz('20260715084649Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930003732207843604)
,p_plug_name=>'Custom'
,p_static_id=>'custom'
,p_parent_plug_id=>wwv_flow_imp.id(17930003534850843602)
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4> What is it?</h4>',
'<p>Allows you to create <strong>your own authentication logic</strong> using PL/SQL.</p>',
'<ul>',
'    <li>Username validation</li>',
'    <li>Password validation</li>',
'    <li>OTP</li>',
'    <li>Biometric</li>',
'    <li>API authentication</li>',
'    <li>Token authentication</li>',
'</ul>',
'<h4> Use Case </h4>',
'<p>Most enterprise applications.</p>',
'<h4>Example</h4>',
'<p>Suppose your users are stored in:</p>',
'<code>',
'APP_USERS',
'----------',
'USER_ID',
'USERNAME',
'PASSWORD',
'STATUS',
'</code>',
'<p>Authentication Function</p>',
'<code>',
'FUNCTION authenticate (',
'    p_username IN VARCHAR2,',
'    p_password IN VARCHAR2',
') RETURN BOOLEAN',
'IS',
'    l_count NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'    INTO l_count',
'    FROM app_users',
'    WHERE username = p_username',
'    AND password = p_password;',
'',
'    RETURN l_count = 1;',
'END;',
'</code>',
'<h4>Advantages</h4>',
'<ul>',
'    <li>Completely customizable</li>',
'    <li>Can use encrypted passwords</li>',
'    <li>Can call REST APIs</li>',
'    <li>Can use OAuth</li>',
'    <li>Can use LDAP</li>',
'    <li>Can implement OTP</li>',
'</ul>',
'<h4>Disadvantages</h4>',
'<ul>',
'    <li>More coding required</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260715084452Z')
,p_updated_on=>wwv_flow_imp.dz('20260715084649Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
