wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930003878619843605)
,p_plug_name=>'Database Accounts'
,p_static_id=>'database-accounts'
,p_parent_plug_id=>wwv_flow_imp.id(17930003534850843602)
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4> What is it?</h4>',
'<p>Authenticates users using <strong>Oracle Database users</strong>.</p>',
'<p>For example,</p>',
'<ul>',
'    <li>SYS</li>',
'    <li>SYSTEM</li>',
'    <li>HR</li>',
'    <li>SCOTT</li>',
'</ul>',
'<P>These database users log directly into your application.</P>',
'<h4>Example</h4>',
'<p>Username: HR</p>',
'<p>Password: hr123</p>',
'<p>If HR exists in Oracle Database, login succeeds.</p>',
'<h4>Advantages</h4>',
'<ul>',
'    <li>No custom table required</li>',
'    <li>Uses Oracle Database authentication</li>',
'</ul>',
'<h4>Disadvantages</h4>',
'<ul>',
'    <li>Every application user must have a database account</li>',
'    <li>Not recommended for public applications</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
