);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930003967938843606)
,p_plug_name=>'HTTP Header Variable'
,p_static_id=>'http-header-variable'
,p_parent_plug_id=>wwv_flow_imp.id(17930003534850843602)
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4> What is it?</h4>',
'<p>Authentication is done by another system (web server, SSO, proxy,reverse proxy).</p>',
'<p>APEX simply reads a username from an HTTP header.</p>',
'<h4>Example Header</h4>',
'<p>REMOTE_USER = john</p>',
'<p>APEX trusts the header.</p>',
'<h4>Common Use</h4>',
'<ul>',
'    <li>Oracle HTTP Server</li>',
'    <li>Apache</li>',
'    <li><Nginx/li>',
'    <li>Reverse Proxy</li>',
'    <li>COrporate SSO</li>',
'    <li></li>',
'</ul>',
'<h4>Advantages</h4>',
'<ul>',
'    <li>Very fast</li>',
'    <li>Centralized authentication</li>',
'</ul>',
'<h4>Disadvantages</h4>',
'<ul>',
'    <li>Requires web server configuration</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260715095106Z')
