,p_plug_display_sequence=>50
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4> What is it?</h4>',
'<p>Authenticates users against an <strong>LDAP server.</strong></p>',
'<p>Popular LDAP servers',
'    <ul>',
'        <li>Microsoft Active Directory</li>',
'        <li>Oracle Internet Directory</li>',
'        <li>OpenLDAP</li>',
'    </ul>',
'</p>',
'<h4>Example</h4>',
'<p>Employee Login</p>',
'<p>Username: john</p>',
'<p>Password: ********</p>',
'<p>APEX asks active Directory wheter the credentials are valid.</p>',
'<h4>Advantages</h4>',
'<ul>',
'    <li>Corporate login</li>',
'    <li>Central user management</li>',
'</ul>',
'<h4>Disadvantages</h4>',
'<ul>',
'    <li>LDAP server required</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
