,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4> What is it?</h4>',
'<p>No login screen</p>',
'<p>Anyone can open the application.</p>',
'<h4>Example</h4>',
'<p>URL : https://server/ords/r/demo/home</p>',
'<p>The page opens immediately.</p>',
'<h4>Use Cases</h4>',
'<ul>',
'    <li>Public website</li>',
'    <li>Public reports</li>',
'    <li>Documentation</li>',
'    <li>Demo application</li>',
'</ul>',
'<h4>Advantages</h4>',
'<ul>',
'    <li>Very simple</li>',
'</ul>',
'<h4>Disadvantages</h4>',
'<ul>',
'    <li>No security</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
