wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930004254498843609)
,p_plug_name=>'Open Door Credentials'
,p_static_id=>'open-door-credentials'
,p_parent_plug_id=>wwv_flow_imp.id(17930003534850843602)
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>70
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4> What is it?</h4>',
'<p>A development/testing authentication where APEX accepts any username/password without validating against a user store.</p>',
'<h4>Example</h4>',
'<p>Username : abc</p>',
'<p>Password : xyz</p>',
'<p>Login succeeds because credentials are not actually verified.</p>',
'<h4>Use Cases</h4>',
'<ul>',
'    <li>Development</li>',
'    <li>Testing</li>',
'    <li>Local demos</li>',
'</ul>',
'<h4>Advantages</h4>',
'<ul>',
'    <li>Very quick for testing</li>',
'</ul>',
'<h4>Disadvantages</h4>',
'<ul>',
'    <li>Never use in production</li>',
'    <li>Not secure</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
