wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930004315745843610)
,p_plug_name=>'Oracle APEX Accounts'
,p_static_id=>'oracle-apex-accounts_1'
,p_parent_plug_id=>wwv_flow_imp.id(17930003534850843602)
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>80
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4>What is it?</h4>',
'<p>Uses users stored in the <strong>Oracle APEX workspace.</strong></p>',
'<p>These are workspace users managed by an administrator.</p>',
'<p>Example users : ADMIN, DEV1, DEV2, JOHN</p>',
'<h4>Use Case</h4>',
'<p>Internal company applications.</p>',
'<h4>Example</h4>',
'<p>Workspace USer --> Username: JOHN --> Password: *******</p>',
'<h4>Advantages</h4>',
'<ul>',
'    <li>Easy setup</li>',
'    <li>No custom user table</li>',
'    <li>Password policy handled by APEX</li>',
'</ul>',
'<h4>Disadvantages</h4>',
'<ul>',
'    <li>Users must exist in the workspace</li>',
'    <li>Less suitable for large external user bases</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
