wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662359755192076061)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>'<p>In Oracle APEX, an <strong>authentication scheme</strong> is <b>the mechanism used to verify a user''s identity before granting them access to an application.</b> Developers can choose from several buil-in, preconfigured schemes or create custom on'
||'es using PL/SQL. The chosen scheme determines how credentials are checked and how user sessions are managed.</p>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17930004426995843611)
,p_plug_name=>'Social Sign-In'
,p_static_id=>'social-sign-in'
,p_parent_plug_id=>wwv_flow_imp.id(17930003534850843602)
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>90
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4>What is it?</h4>',
'<p>Allows users to log in using external identity providers via OAuth 2.0/OpenID Connect.</p>',
'<p>Examples include:',
'    <ul>',
'        <li>Google</li>',
'        <li>Microsoft</li>',
'        <li>GitHub</li>',
'        <li>Facebook(where supported)</li>',
'        <li>Apple</li>',
'        <li>Other OpenID Connect providers</li>',
'    </ul>',
'</p>',
'<h4>Example</h4>',
'<p>User clicks : Continue with Google</p>',
'<p>Googke authenticates the user and returns their identity to APEX.</p>',
'<h4>Advantages</h4>',
'<ul>',
'    <li>No password storage in your application</li>',
'    <li>Better user experience</li>',
'    <li>Supports MFA from the identity provider</li>',
'</ul>',
'<h4>Disadvantages</h4>',
'<ul>',
'    <li>Requires PAuthe/OpenID Connect Configuration</li>',
'    <li>Internet connectivity is usually required</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260715095106Z')
,p_updated_on=>wwv_flow_imp.dz('20260715095155Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
