wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662893042536901118)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody:margin-bottom-md'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>'<p>Authorization is a broad term for controlling access to resources based on user privileges. While conditions control the rendering and processing of specific page controls or components, authorization schemes control user access to specific contro'
||'ls or components.</p>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662893506441901122)
,p_plug_name=>'Validate authorization scheme attribute'
,p_static_id=>'validate-authorization-scheme-attribute'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody:margin-top-md'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li><b>Once per session -</b> Evaluate only once and always use the memorized result afterwards.</li>',
'    <li><b>Once per page view -</b> Evaluate once for each request that is processed. Use the memorized result if the authorization scheme is referenced in more than one component on the page.</li>',
'    <li><b>Once per component -</b> Evaluate once for each component that references the authorization scheme, but save the result in the session. Further requests to render or process the scheme use the result that was memorized for the component.</'
||'li>',
'    <li><b>Always(No Caching) -</b> The authorization scheme will always be evaluated.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
/
