wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662893612243901124)
,p_plug_name=>'About Adding Access Control'
,p_static_id=>'about-adding-access-control'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody:margin-bottom-md'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li>Adds an Access Control region to the Administration page you specify.</li>',
'    <li>Creates the access roles: <b>Administrator, Contributor and Reader.</b></li>',
'    <li>Creates the authorization schemes: <b>Administration Rights, Contribution Rights, and Reader Rights.</b></li>',
'    <li>Creates the build option, <b>Feature: Access Control.</b></li>',
'    <li>Creates the Application Setting, <b>ACCESS_CONTROL_SCOPE.</b></li>',
'</ul>',
'<p>Developers use the access control list to associate the privileges, view, edit, and administration, with application users. Within the final Access Control UI, each privileges correlates to an access role:</p>',
'<ul>',
'    <li><b>View</b> correlates to the <b>Reader</b> role.</li>',
'    <li><b>Edit</b> correlates to the <b>Contributor role.</b></li>',
'    <li><b>Administration</b> correlates to the <b>Administrator</b> role.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662894046081901128)
,p_plug_name=>'About Controlling Access for Pages and Page Components'
,p_static_id=>'about-controlling-access-for-pages-and-page-components'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody:margin-top-md'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>60
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>You can control access to a specific page or page component by editing the page or component and selecting one of the following authorization schemes:</p>',
'<ul>',
'    <li><b>Administration Rights -</b> Only Administrators can see the page/component.</li>',
'    <li><b>Contribution Rights -</b> Administrators and Editors can see it; <b>View-only users cannot.</b></li>',
unistr('    <li><b>Reader Rights \2013</b> All users (Administrator, Editor, Viewer) can see it.</li>'),
unistr('    <li><b>Not Administration Rights \2013</b> Administrators cannot see it.</li>'),
unistr('    <li><b>Not Contribution Rights \2013</b> Only View users can see it; Administrators and Editors cannot.</li>'),
unistr('    <li><b>Not Reader Rights \2013</b> No users (Administrator, Editor, Viewer) can see it.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
