wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662895880052901146)
,p_plug_name=>'Introduction'
,p_static_id=>'introduction'
,p_parent_plug_id=>wwv_flow_imp.id(7662895796512901145)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>Navigate to the Shared Components page:',
'        <ul>',
'            <li>On the Workspace home page, click <b>App Builder</b></li>',
'            <li>Select an application.</li>',
'            <li>On the Application home page, click <b>Shared Components.</b></li>',
'        </ul>',
'    </li>',
'    <li>Under Other Components, select <b>Lists of Values.</b></li>',
'    <li>Run the Create List of Values Wizard. On the Lists of Values page, click <b>Create.</b></li>',
'    <li>In the Create List of Values Wizard:',
'        <ul>',
'            <li>Source:',
'                <ul>',
'                    <li>Create List of Values - Specify how to Create a list of values. For example, select <b>From Scratch.</b></li>',
'                    <li>Click <b>Next.</b></li>',
'                </ul>',
'            </li>',
'            <li>Name and Type:',
'                <ul>',
'                    <li>Name - Enter a name for the list of values. For example: <b>STATUS</b></li>',
'                    <li>Type - Select <b>Static.</b></li>',
'                    <li>Click <b>Next.</b></li>',
'                </ul>',
'            </li>',
'            <li>Static Values: Enter static display and return values. For this example, enter the following',
'                <ul>',
'                    <li>Sequence 1:',
'                        <ul>',
'                            <li>Display Value - Pending</li>',
'                            <li>Return Value - Pending</li>',
'                        </ul>',
'                    </li>',
'                    <li>Sequence 2:',
'                        <ul>',
'                            <li>Display Value - Open</li>',
'                            <li>Return Value - Open</li>',
'                        </ul>',
'                    </li>',
'                    <li>Sequence 3:',
'                        <ul>',
'                            <li>Display Value - On-Hold</li>',
'                            <li>Return Value - On-Hold</li>',
'                        </ul>',
'                    </li>',
'                    <li>Sequence 4:',
'                        <ul>',
'                            <li>Display Value - Closed</li>',
'                            <li>Return Value - Closed</li>',
'                        </ul>',
'                    </li>',
'                </ul>',
'            </li>',
'            <li>Click <b>Create List of Values.</b></li>',
'        </ul>',
'    </li>',
'    <li>In Page Designer, update the form item to reference the list of values:',
'        <ul>',
'            <li>Return to Page Designer. Click <b>Edit Page X</b> on the Page Designer toolbar where X is the page number.</li>',
'            <li>Select the form item (e.g., P3_STATUS).</li>',
'            <li>In the Property Editor, set:',
'                <ul>',
'                    <li><b>Type:</b> Radio Group</li>',
'                    <li><b>List of Values Type:</b> Shared Component</li>',
'                    <li><b>List of Values:</b> STATUS</li>',
'                    <li><b>Display Extra Values:</b> Disabled</li>',
'                </ul>',
'            </li>',
'            <li>Click <b>save</b> and run the page.</li>',
'        </ul>',
'    </li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
