,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>Navigate to the Shared Components page:',
'        <ul>',
'            <li>On the Workspace home page, click <b>App Builder.</b></li>',
'            <li>Select an application.</li>',
'            <li>On the Application home page, click <b>Shared Components.</b></li>',
'        </ul>',
'    </li>',
'    <li>Under Other Components, select <b>Lists of Values.</b></li>',
'    <li>Select a list of values.',
'        <ul>',
'            <li><b>Static List of Values -</b> Click the Edit icon edit a value or the sequence. Click Add Row to add more Display/Return value combinations.</li>',
'            <li><b>Dynamic List of Values -</b> Edit the attributes to reconfigure the Source or Column Mappings.</li>',
'            <li>Use <b>Additional Display Columns</b> to define additional display columns for item types that support multiple display columns, such as Popup LOV. If adding additional display columns, ensure that the return column is included in the'
||' column list. If you do not want it displayed to users, set the return column to <b>Visible No</b> and <b>Searchable No.</b></li>',
'        </ul>',
'    </li>',
'    <li>Click <b>Apply Changes</b> to save your changes.</li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663363490901387015)
,p_plug_name=>'Key Uses and Benefits'
,p_static_id=>'key-uses-and-benefits'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li><b>Data Integrity:</b> Restricts user input to a specific set of valid values, preventing invalid data entry.</li>',
'    <li><b>Improved Usability:</b> Replaces manual entry of IDs (e.g., Department ID) with user-friendly display values (e.g., Department Name) through item types like select lists, radio groups, and popup LOVs.</li>',
'    <li><b>Reusability:</b> Defining an LOV as a Shared Component allows it to be used across multiple pages and applications, making maintenance easier.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7662895634038901144)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody:margin-bottom-sm'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>A list of values is a static or dynamic definition used to display a specific type of page item.</p>',
'<p>Advantages of creating a list of values as a shared component include:</p>',
'<ol>',
'    <li>A list of values created as a shared component can be added to any page within an application.</li>',
'    <li>All list of values definitions are stored in one location, making them easy to locate and update.</li>',
'    <li>You can define lists of values on different data sources and make use of new functionality only included in Shared LOVs, for example multi-column support, icon and grouping columns.</li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
