,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>Navigate to Plug-ins',
'        <ul>',
'            <li>From the workspace home page, go to <b>App Builder.</b></li>',
'            <li>Select an application and click <b>Shared Components.</b></li>',
'            <li>Under <b>Other Components,</b> click <b>Plug-ins</b> and then <b>Create.</b></li>',
'        </ul>',
'    </li>',
'    <li>Copy an Existing Plug-in',
'        <ul>',
'            <li>Select <b>As a copy of an Existing Plug-in</b> and click <b>Next.</b></li>',
'            <li>Choose the <b>Application</b> and <b>Theme</b> from which to copy the plug-in.</li>',
'            <li>Click <b>Next.</b></li>',
'        </ul>',
'    </li>',
'    <li>Select Plug-in to Copy',
'        <ul>',
'            <li>Identify the plg-in and select the appropriate option:',
'                <ul>',
'                    <li><b>Yes</b> - Copy the Plug-in</li>',
'                    <li><b>No</b> - Do not copy the plug-in</li>',
'                    <li><b>Copy and Subscribe</b> - Copy the plug-in and create a subscription to the master plug-in</li>',
'                </ul>',
'            </li>',
'            <li>Click <b>Copy Plug-ins</b> to finish.</li>',
'        </ul>',
'    </li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
