,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>Navigate to Plug-ins    ',
'        <ul>',
'            <li>From the Workspace home page, go to <strong>App Builder</strong>.</li>',
'            <li>Select an application and click <strong>Shared Components</strong>.</li>',
'            <li>Under <strong>Other Components</strong>, click <strong>Plug-ins</strong> and then <strong>Create</strong>.</li>',
'        </ul>',
'    </li>',
'    <li>Create the Plug-in',
'        <ul>',
'            <li>Select <strong>From Scratch</strong> and click <strong>Next</strong>.</li>',
'            <li><strong>Name:</strong> Enter the plug-in name.</li>',
'            <li><strong>Internal Name:</strong> Enter a unique internal name (for example, <code>COM.EXAMPLE.SLIDER</code>).</li>',
'            <li><strong>Type:</strong> Select the component type (Authentication, Authorization, Item, Region, Dynamic Action, Process, REST Data Source, or Template Component).</li>',
'            <li><strong>Category:</strong> (Dynamic Action only) Select the display category.</li>',
'        </ul>',
'    </li>',
'    <li>Define Source and Attributes',
'        <ul>',
'            <li><strong>PL/SQL Code:</strong> Provide rendering, execution, and callback logic (or reference a PL/SQL package).</li>',
'            <li><strong>Callbacks / Standard Attributes:</strong> Configure based on the selected plug-in type.</li>',
'            <li><strong>Validation Option:</strong> Choose whether PL/SQL is parsed at creation time or runtime.</li>',
'        </ul>',
'    </li>',
'    <li>Provide Information',
'        <ul>',
'            <li>Enter <strong>Version</strong>, <strong>About URL</strong>, <strong>Help Text</strong>, and optional <strong>Comments</strong>.</li>',
'        </ul>',
'    </li>',
'    <li>Finish',
'        <ul>',
'            <li>Click <strong>Create Plug-in</strong> to save.</li>',
'        </ul>',
'    </li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
