wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663365621838387037)
,p_plug_name=>'Copying and Subscribing to a Component Group'
,p_static_id=>'copying-and-subscribing-to-a-component-group'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>60
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>Navigate to the Shared Components, Component Groups page:',
'        <ul>',
'            <li>On the Workspace home page, click <b>App Builder</b></li>',
'            <li>Select an application.</li>',
'            <li>On the Application home page, click <b>Shared Components.</b></li>',
'            <li>Under Other Components, click <b>Component Groups.</b></li>',
'        </ul>',
'    </li>',
'    <li>Search for the component group and click <b>Copy</b> in the Copy column.</li>',
'    <li>New Component Group Name - Enter the name of the component group. The component group name must be unique within the application.</li>',
'    <li>Click <b>Copy Component Group.</b></li>',
'    <li>From the Tasks region on the Component Groups page, click <b>Copy from another app.</b></li>',
'    <li>Application - Select the application from which you want to copy.</li>',
'    <li>Component Group - Select the component group to copy.</li>',
'    <li>Subscribe - Set this flag to <b>On</b> to subscribe to the component group.</li>',
'    <li>Click <b>Next.</b></li>',
'    <li>Review the actions column for each component.',
'        <ul>',
'            <li>Add: A new component will be added to the target application.</li>',
'            <li>Refresh: An existing component will be reused after refresh.</li>',
'            <li>Replace: An existing component will be replaced with the master component.</li>',
'            <li>Reuse: An existing component will be reused.</li>',
'        </ul>',
'    </li>',
'    <li>Click <b>Copy Component Group.</b></li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663365530521387036)
,p_plug_name=>'Creating a Component Group'
,p_static_id=>'creating-a-component-group'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody:margin-bottom-sm'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>Access the Component Groups page:',
'        <ul>',
'            <li>On the Workspace home page, click the <b>App Builder</b> icon.</li>',
'            <li>Select an application.</li>',
'            <li>On the Application home page, click <b>Shared Components.</b></li>',
'            <li>Under Other Components, click <b>Component Groups.</b></li>',
'            <li>Click <b>Create.</b></li>',
'        </ul>',
'    </li>',
'    <li>For Name and Comments:',
'        <ul>',
'            <li>Name - Enter the name of the component group. The component group name must be unique within the application.</li>',
'            <li>Comments - Enter a brief description of this component group.</li>',
'            <li>Click <b>Create.</b></li>',
'        </ul>',
'    </li>',
'    <li>Click <b>Assign Components.</b></li>',
'    <li>Select the <b>Component Type</b> from the available options.</li>',
'    <li>From the available components, select components for the component group using <b>Reset, Move All, Move, Remove, and Remove All.</b></li>',
'    <li>Assign the components to the component group:',
'        <ul>',
'            <li>Click <b>Assign and Assign More</b> to assign the selected components, and then continue selecting more components of a different component type.</li>',
'            <li>Click <b>Assign</b> to assign the selected components and return to the component group details screen.</li>',
'            <li>Click <b>Cancel</b> to return to the component group details screen.</li>',
'        </ul>',
'    </li>',
'    <li>Click <b>Unassign from Component Group.</b></li>',
'    <li>Click <b>Apply Changes.</b></li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
