,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li><b>Reusability:</b> Allows a set of related shared components to be defined once (in a "master" application) and reused in multiple other applications.</li>',
'    <li><b>Consistency:</b> Ensures that components like authentication schemes, themes, or custom templates are consistent across various applications within a workspace.</li>',
'    <li><b>Bulk Management:</b> Enables the bulk refresh or publishing of changes from the master component group to all subscribing component groups with a single action.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
