wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663367389231387054)
,p_plug_name=>'Steps to Create Data Load Definition'
,p_static_id=>'steps-to-create-data-load-definition'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li><b>Navigate to Shared Components:</b>',
'        <ul>',
'            <li>From the Oracle APEX Workspace home page, click <b>App Builder</b> and select your application.</li>',
'            <li>On the Application home page, click <b>Shared Components.</b></li>',
'            <li>Under the "Other Components" section, click <b>Data Load Definitions.</b></li>',
'        </ul>',
'    </li>',
'    <li><b>Start the Create Process:</b>',
'        <ul>',
'            <li>Click the <b>Create</b> button.</li>',
'            <li>On the "Method" screen, select <b>From Scratch</b> and click <b>Next.</b></li>',
'        </ul>',
'    </li>',
'    <li><b>Define the Target:</b>',
'        <ul>',
'            <li><b>Name:</b> Enter a name for your Data Load Definition.</li>',
'            <li><b>Target Type:</b> Specify whether the data will be loaded into a database <b>Table</b> or an APEX Collection</li>',
'            <li><b>Table Owner:</b> Select the schema owner of the target table.</li>',
'            <li><b>Table Name:</b> Select the specific table to which data will be loaded.</li>',
'            <li>Click <b>Next.</b></li>',
'        </ul>',
'    </li>',
'    <li><b>Provide Sample Data:</b>',
'        <ul>',
'            <li><b>Source Type:</b> Choose how to provide sample data to build the definition(e.g.,<b>Upload a File</b> or <b>Copy and Paste</b> delimited data).</li>',
'            <li>Upload or paste your sample data.</li>',
'            <li>Click <b>Next.</b></li>',
'        </ul>',
'    </li>',
'    <li><b>Map Columns:</b>',
'        <ul>',
'            <li>APEX automatically attempts to map the columns in your sample data to the columns in the target table.</li>',
'            <li>Review and adjust the column mappings as needed. You can also define which columns form the <b>Primary Key.</b></li>',
'             <li>Click <b>Next.</b></li>',
'        </ul>',
'    </li>',
'    <li><b>Create the Definition and Page:</b>',
'        <ul>',
'            <li><b>Create Data Load</b> (creates just the definition, and you can add a page later).</li>',
'            <li><b>Create and Add Page</b> (creates the definition and a functional data loading page simultaneously).</li>',
'        </ul>',
'    </li>',
'    <li><b>Test the Page:</b>',
'        <ul>',
'            <li>If you chose "Create and Add Page," click <b>Save and Run Page</b> to test the new data loading functionality within your application.</li>',
'        </ul>',
'    </li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
/
