wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7657027829978981961)
,p_plug_name=>'Image'
,p_static_id=>'image'
,p_region_template_options=>'#DEFAULT#:t-ImageRegion--auto:t-ImageRegion--contain:t-ImageRegion--square:t-ImageRegion--noFilter'
,p_plug_template=>1676876785387892020
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!DOCTYPE html>',
'<html lang="en">',
'<head>',
'    <meta charset="UTF-8">',
'    <title>Navigation Bar List in Oracle APEX</title>',
'</head>',
'<body>',
'',
'    <h2>Navigation Bar List in Oracle APEX</h2>',
'',
'    <h3>Overview</h3>',
'    <p>',
'        Navigation Bar List is a component in Oracle APEX used to display navigation options ',
'        in the top right corner of the application. It provides quick access to important ',
'        functions such as user profile, settings, logout, and other navigation links.',
'    </p>',
'',
'    <h3>Purpose of Navigation Bar List</h3>',
'',
'    <ul>',
'        <li>To provide quick access to important application links.</li>',
'        <li>To display user-related options such as profile and logout.</li>',
'        <li>To improve application navigation and usability.</li>',
'        <li>To create a standard navigation menu in the application header.</li>',
'    </ul>',
'',
'    <h3>Steps to Create Navigation Bar List</h3>',
'',
'    <ol>',
'        <li>',
'            Go to <strong>App Builder</strong>.',
'        </li>',
'',
'        <li>',
'            Select your <strong>Application</strong>.',
'        </li>',
'',
'        <li>',
'            Click on <strong>Shared Components</strong>.',
'        </li>',
'',
'        <li>',
'            Under <strong>Navigation and Search</strong>, click <strong>Lists</strong>.',
'        </li>',
'',
'        <li>',
'            Click <strong>Create</strong>.',
'        </li>',
'',
'        <li>',
'            Select <strong>Create List</strong> and click <strong>Next</strong>.',
'        </li>',
'',
'        <li>',
'            Enter the <strong>Name</strong> as Navigation Bar.',
'        </li>',
'',
'        <li>',
'            Click <strong>Create List</strong>.',
'        </li>',
'',
'        <li>',
'            Click <strong>Create List Entry</strong>.',
'        </li>',
'',
'        <li>',
'            Enter the required details:',
'            <ul>',
'                <li>Name (Example: Logout)</li>',
'                <li>Target (Example: &LOGOUT_URL.)</li>',
'                <li>Icon (Example: fa-sign-out)</li>',
'            </ul>',
'        </li>',
'',
'        <li>',
'            Click <strong>Create List Entry</strong>.',
'        </li>',
'',
'    </ol>',
'',
'    <h3>Important Fields Explanation</h3>',
'',
'    <ul>',
'        <li>',
'            <strong>Name</strong><br>',
'            Defines the name of the navigation bar list.',
'        </li>',
'',
'        <li>',
'            <strong>Sequence</strong><br>',
'            Defines the order in which list entries appear.',
'        </li>',
'',
'        <li>',
'            <strong>Icon</strong><br>',
'            Displays an icon for the navigation item.',
'        </li>',
'',
'        <li>',
'            <strong>Target</strong><br>',
'            Defines the page or URL where the navigation link will go.',
'        </li>',
'',
'        <li>',
'            <strong>Authorization Scheme</strong><br>',
'            Controls which users can see the navigation item.',
'        </li>',
'',
'    </ul>',
'',
'    <h3>Example of Navigation Bar List</h3>',
'',
'    <p>',
'        Install App<br>',
'        User Profile<br>',
'        Logout',
'    </p>',
'',
'    <h3>Use in Training Application</h3>',
'',
'    <p>',
'        In the Training Application, Navigation Bar List is used to display options such as ',
'        Install App, User Name, and Logout in the application header. This allows users to ',
'        easily access important functions and manage their session.',
'    </p>',
'',
'    <h3>Conclusion</h3>',
'',
'    <p>',
'        Navigation Bar List is an important component in Oracle APEX that helps users ',
'        navigate the application easily and access important options like profile and logout.',
'    </p>',
'',
'</body>',
'</html>',
''))
,p_region_image=>'https://g64cf2f956d7752-playground01.adb.us-ashburn-1.oraclecloudapps.com/ords/dev_tavish1/image/get?IMAGE_STATIC_ID=NAVIGATION_BAR_LIST'
