wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663334773658442835)
,p_plug_name=>'Instructions'
,p_static_id=>'instructions'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'',
'<li>Login to <b>Oracle APEX</b> and open your <b>Workspace</b></li>',
'',
'<li>Click on <b>App Builder</b></li>',
'',
'<li>Select your <b>Application</b></li>',
'',
'<li>Click on <b>User Interfaces</b></li>',
'',
'<li>Select the <b>Desktop User Interface</b> or click <b>Create</b></li>',
'',
'<li>Configure the following settings:</li>',
'',
'<ol>',
'',
'<li>Go to <b>Icon</b> and upload application icons</li>',
'',
'<li>Go to <b>Logo</b> and select <b>Logo Type</b> (Text, Image, or Image and Text)</li>',
'',
'<li>Enter the <b>Application Name</b> in the Text field</li>',
'',
'<li>Go to <b>Navigation Menu</b> and select the <b>Navigation Menu List</b></li>',
'',
'<li>Select the <b>Position</b> (Side or Top)</li>',
'',
'<li>Go to <b>Navigation Bar</b> and select the <b>Navigation Bar List</b></li>',
'',
'</ol>',
'',
'<li>Click on <b>Apply Changes</b></li>',
'',
'<li>Run the <b>Application</b> to see the User Interface</li>',
'',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
