 p_id=>wwv_flow_imp.id(7666718974015259320)
,p_plug_name=>'JavaScript and Cascading Style Sheets'
,p_static_id=>'javascript-and-cascading-style-sheets-2'
,p_parent_plug_id=>wwv_flow_imp.id(7666718741171259318)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4>1. JavaScript File URLs</h4>',
'',
'<p>',
'This field is used to add JavaScript files at the Theme level.',
'All JavaScript files written here are automatically loaded',
'on every page of the Oracle APEX application.',
'</p>',
'',
'<h4>Why It Is Used:</h4>',
'<ul>',
'    <li>To add global JavaScript functionality.</li>',
'    <li>To perform client-side validation.</li>',
'    <li>To control page events and button actions.</li>',
'    <li>To add animation or dynamic behavior.</li>',
'</ul>',
'',
'',
'<h4>How It Works:</h4>',
'<p>',
'When the application runs, Oracle APEX loads all JavaScript',
'files mentioned in this section automatically for all pages.',
'</p>',
'',
'<h4>2. CSS File URLs</h4>',
'',
'<p>',
'This field is used to add Cascading Style Sheet (CSS) files',
'which control the design and appearance of the application.',
'</p>',
'',
'<h4>Why It Is Used:</h4>',
'<ul>',
'    <li>To change application colors and themes.</li>',
'    <li>To customize buttons and regions.</li>',
'    <li>To modify fonts and layouts.</li>',
'    <li>To create professional UI design.</li>',
'</ul>',
'',
'<h4>How It Works:</h4>',
'<p>',
'CSS files added here automatically apply styling to all',
'pages, reports, forms, and regions of the application.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
