 p_id=>wwv_flow_imp.id(7663337395838442861)
,p_plug_name=>'Instructions'
,p_static_id=>'instructions'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'<li>Login to <b>Oracle APEX Workspace</b></li>',
'<li>Click on <b>App Builder</b></li>',
'<li>Select your <b>Application</b></li>',
'<li>Click on <b>Shared Components</b></li>',
'<li>Under User Interface, click on <b>Templates</b></li>',
'<li>Click on <b>Create</b></li>',
'<li>Enter <b>Template Name</b></li>',
'<li>Select <b>Template Type</b></li>',
'<li>Select <b>Theme</b></li>',
'<li>Select <b>Template Class</b></li>',
'<li>Click on <b>Create</b> to save the template</li>',
'</ol>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
