,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'',
'<li>Login to <b>Oracle APEX Workspace</b></li>',
'',
'<li>Click on <b>App Builder</b></li>',
'',
'<li>Select your <b>Application</b></li>',
'',
'<li>Click on <b>Shared Components</b></li>',
'',
'<li>Under <b>Logic</b>, click on <b>Email Templates</b></li>',
'',
'<li>Click on <b>Create</b></li>',
'',
'<li>Enter <b>Template Name</b></li>',
'',
'<li>Enter <b>Static Identifier</b></li>',
'',
'<li>Enter <b>Email Subject</b></li>',
'',
'<li>Go to <b>HTML Format</b> section</li>',
'',
'<li>Enter email content in <b>Header</b> (optional)</li>',
'',
'<li>Enter email message in <b>Body</b></li>',
'',
'<li>Enter email footer in <b>Footer</b> (optional)</li>',
'',
'<li>Click on <b>Create Email Template</b></li>',
'',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7664028895579908314)
,p_plug_name=>'Use of Email Template'
,p_static_id=>'use-of-email-template'
,p_parent_plug_id=>wwv_flow_imp.id(7664028625939908312)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_display_column=>9
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'',
'<li><b>Template Name:</b>',
'<ul>',
'<li>This field is used to define the name of the email template.</li>',
'<li>It helps identify and select the template when sending emails.</li>',
'</ul>',
'</li>',
'',
'<li><b>Static Identifier:</b>',
'<ul>',
'<li>This field is used to define a unique identifier for the template.</li>',
'<li>It is used in PL/SQL or processes to reference the template.</li>',
'</ul>',
'</li>',
'',
'<li><b>Email Subject:</b>',
'<ul>',
'<li>This field is used to define the subject line of the email.</li>',
'<li>This subject appears when the email is received.</li>',
'</ul>',
'</li>',
'',
'<li><b>Supports Template Directives:</b>',
'<ul>',
'<li>This field shows whether the template supports dynamic values.</li>',
'<li>It allows use of placeholders like #NAME# or #DATE#.</li>',
'</ul>',
'</li>',
'',
'<li><b>Header (HTML Format):</b>',
'<ul>',
'<li>This field is used to define the header section of the email.</li>',
'<li>It usually contains logo, title, or top design.</li>',
'</ul>',
'</li>',
'',
'<li><b>Body (HTML Format):</b>',
'<ul>',
'<li>This field is used to define the main content of the email.</li>',
'<li>It contains the message and dynamic data.</li>',
'</ul>',
'</li>',
'',
'<li><b>Footer (HTML Format):</b>',
'<ul>',
'<li>This field is used to define the footer section of the email.</li>',
'<li>It usually contains contact information, copyright, or links.</li>',
'</ul>',
'</li>',
'',
'</ol>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
