 p_id=>wwv_flow_imp.id(7664029549822908321)
,p_plug_name=>'Instructions to Apply Map Background'
,p_static_id=>'instructions-to-apply-map-background'
,p_parent_plug_id=>wwv_flow_imp.id(7664029488958908320)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_grid_column_span=>4
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'',
'<li>',
'Open Page Designer',
'<ul>',
'<li>Login to <b>Oracle APEX</b>.</li>',
'<li>Open your <b>Application</b>.</li>',
'<li>Open the desired <b>Page</b> in <b>Page Designer</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Select Map Region',
'<ul>',
'<li>In the <b>Rendering</b> tab (left pane), select the <b>Map Region</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Open Attributes',
'<ul>',
'<li>In the <b>Property Editor</b> (right pane), click on the <b>Attributes</b> tab.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Set Map Background',
'<ul>',
'<li>In the <b>Map</b> group, find the <b>Background</b> attribute.</li>',
'<li>Select <b>Shared Component</b> as the Background type.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Select Map Background Name',
'<ul>',
'<li>In the <b>Standard</b> field, select the map background you created.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Save and Run Page',
'<ul>',
'<li>Click on <b>Save</b>.</li>',
'<li>Run the page to see the <b>custom map background</b> applied.</li>',
'</ul>',
'</li>',
'',
'</ol>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
