 p_id=>wwv_flow_imp.id(7664029335122908319)
,p_plug_name=>'Use of Map Background'
,p_static_id=>'use-of-map-background'
,p_parent_plug_id=>wwv_flow_imp.id(7664029042269908316)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_grid_column_span=>5
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    ',
'<li>',
'Prepare Map Service Details',
'<ul>',
'<li>Get the required <b>Map URL</b> and <b>API Key</b> from a map service provider such as <b>ArcGIS</b> or <b>Google Maps</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Open Shared Components',
'<ul>',
'<li>Login to <b>Oracle APEX</b>.</li>',
'<li>Open your <b>Application</b>.</li>',
'<li>Click on <b>Shared Components</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Open Map Backgrounds',
'<ul>',
'<li>Under <b>Other Components</b>, click on <b>Map Backgrounds</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Create New Map Background',
'<ul>',
'<li>Click on the <b>Create</b> button.</li>',
'<li>The <b>Create Map Background Wizard</b> will open.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Enter Map Background Name',
'<ul>',
'<li>Enter a <b>Name</b> to identify the map background.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Select Map Tile Layer Type',
'<ul>',
'<li><b>Vector Tile Layer:</b> Used to retrieve a map layer from a style.json file.</li>',
'<li><b>Raster XYZ Tile Layer:</b> Used to render raster tiles using x, y, and z values in the URL.</li>',
'<li><b>OGC WMS:</b> Used to retrieve map layers from Open Geospatial Consortium Web Map Service.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Enter Map URL and API Key',
'<ul>',
'<li>Enter the required <b>Map URL</b>.</li>',
'<li>Enter the <b>API Key</b> if required.</li>',
'<li>Use the <b>{api-key}</b> placeholder in the URL if needed.</li>',
'</ul>',
'</li>',
'',
'<li>',
'Create Map Background',
'<ul>',
'<li>Click on <b>Create Map Background</b> to save the configuration.</li>',
'</ul>',
'</li>',
'',
'</ol>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
