 p_id=>wwv_flow_imp.id(7663367667569387057)
,p_plug_name=>'Introduction'
,p_static_id=>'introduction'
,p_parent_plug_id=>wwv_flow_imp.id(7663367575333387056)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>Navigate to the Shared Components page:',
'        <ul>',
'            <li>On the Workspace home page, click <b>App Builder.</b></li>',
'            <li>Select an application.</li>',
'            <li>On the Application home page, click <b>Shared Components.</b></li>',
'        </ul>',
'    </li>',
'    <li>Under <b>Files and Reports,</b> select <b>Static Application Files.</b></li>',
'    <li>On Static Application Files page, click <b>Create File.</b></li>',
'    <li>On the Create page:',
'        <ul>',
'            <li>Directory - Enter the name of the directory where the file should be stored. For example, css or css/images.If no directory is specified, the file is stored in the root directory.</li>',
'            <li>File Name - If creating a blank file (for example, script.js), enter the name of the file.</li>',
'            <li>Content - If uploading a file, do one of the following:',
'                <ul>',
'                    <li>Drag and drop the file to the Content region.</li>',
'                    <li>Click the Content region and select the file.</li>',
'                </ul>',
'            </li>',
'            <li>Click <b>Create</b> or <b>Create and Create Another.</b></li>',
'        </ul>',
'    </li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663367460790387055)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>'<p>Static application files in Oracle APEX are <b>essential, independently managed files such as images, CSS stylesheets, and JavaScript code that are specific to a single application.</b> They are primarily used to manage the look, feel, and client-'
||'side functionality of the application.</p>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
