wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7664029972092908325)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'',
'<li>Login to <b>Oracle APEX Workspace</b></li>',
'',
'<li>Click on <b>App Builder</b></li>',
'',
'<li>Select your <b>Application</b></li>',
'',
'<li>Click on <b>Shared Components</b></li>',
'',
'<li>Under <b>Data Sources</b>, click on <b>REST Data Sources</b></li>',
'',
'<li>Click on <b>Create</b></li>',
'',
'<li>Enter the following details:',
'<ul>',
'<li><b>Name</b> of the REST Data Source</li>',
'<li><b>URL Endpoint</b> (API URL)</li>',
'<li>Select <b>HTTP Method</b> (GET, POST, etc.)</li>',
'</ul>',
'</li>',
'',
'<li>Configure Authentication (if required)</li>',
'',
'<li>Click on <b>Create</b></li>',
'',
'<li>Now you can use this REST Data Source in Reports or Regions</li>',
'',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7664031668993908342)
,p_plug_name=>'Use in Parameters Screen'
,p_static_id=>'use-in-parameters-screen'
,p_parent_plug_id=>wwv_flow_imp.id(7664031506013908340)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_display_column=>8
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'',
'<li>',
'<b>Parameter Type (HTTP Header):</b>',
'<ul>',
'<li>Used to send header information to the API.</li>',
'<li>Example: <b>Content-Type</b> header tells the server what format the data is in.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Parameter Name:</b>',
'<ul>',
'<li>The exact header or parameter name required by the API.</li>',
'<li>Example: <b>Content-Type</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Value:</b>',
'<ul>',
'<li>The value of the header or parameter.</li>',
'<li>Example: <b>application/json</b> (used when sending JSON data).</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Is Static:</b>',
'<ul>',
'<li>If enabled, the value remains fixed.</li>',
'<li>If disabled, value can be dynamic (like a page item).</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>HTTP Method (POST):</b>',
'<ul>',
'<li><b>GET</b> is used to fetch data.</li>',
'<li><b>POST</b> is used to send data to the API.</li>',
'<li>In this screen, POST is selected to send JSON data.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Request Body:</b>',
'<ul>',
'<li>Used to send JSON data to the API when using POST method.</li>',
'<li>This contains the actual data being sent.</li>',
'<li>Example: JSON structure inside curly braces { }.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Discovery Sample:</b>',
'<ul>',
'<li>Upload a sample JSON file.</li>',
'<li>APEX uses it to detect the response structure automatically.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Row Selector:</b>',
'<ul>',
'<li>Used when JSON response is nested.</li>',
'<li>Specifies which JSON node contains the records.</li>',
'<li>If left empty, APEX auto-detects rows.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Discover Button:</b>',
'<ul>',
'<li>Tests the API.</li>',
'<li>Automatically generates data profile.</li>',
'</ul>',
'</li>',
'',
'</ol>',
'',
'<p>',
'This screen is mainly used to configure headers, HTTP method, and request body when sending data to an external REST API.',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7664031870521908344)
,p_plug_name=>' Use in REST Data Source Discovery'
,p_static_id=>'use-in-rest-data-source-discovery'
,p_parent_plug_id=>wwv_flow_imp.id(7664031711935908343)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_grid_column_span=>5
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'',
'<li>',
'<b>Data Tab:</b>',
'<ul>',
'<li>Displays the preview of data fetched from the REST API.</li>',
'<li>Shows records in table format.</li>',
'<li>Used to verify that API is returning correct data.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Data Profile Tab:</b>',
'<ul>',
'<li>Shows detected column structure.</li>',
'<li>Defines data types like Number, Varchar2, Date, etc.</li>',
'<li>Used to confirm column mapping before saving.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Response Body Tab:</b>',
'<ul>',
'<li>Displays the raw JSON response from the API.</li>',
'<li>Used for debugging and checking API structure.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Preview Grid (Columns like City, Price, Status, Property_Id, Property_Name):</b>',
'<ul>',
'<li>Shows API response in structured format.</li>',
'<li>Helps confirm that columns are correctly detected.</li>',
'<li>Ensures correct data will be available for reports.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>More Detail Button:</b>',
'<ul>',
'<li>Shows advanced information about detected columns.</li>',
'<li>Used to review metadata and structure.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Create REST Data Source Button:</b>',
'<ul>',
'<li>Final step to save the REST Data Source.</li>',
'<li>Makes the REST source available in Shared Components.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Navigation Steps Indicator (Top Progress Bar):</b>',
'<ul>',
'<li>Shows progress of REST Data Source creation process.</li>',
'<li>Indicates current step (Preview).</li>',
'</ul>',
'</li>',
'',
'</ol>',
'',
'<p>',
'This screen is used to review and confirm API data before creating the REST Data Source in Oracle APEX.',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
/
