wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7664032103013908346)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'',
'<li>',
'<b>Login to Oracle APEX</b>',
'<ul>',
'<li>Open <b>App Builder</b>.</li>',
'<li>Select your <b>Application</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Open Shared Components</b>',
'<ul>',
'<li>Click on <b>Shared Components</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Go to Duality Views</b>',
'<ul>',
'<li>Under <b>Data Sources</b>, click <b>Duality Views</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Click Create</b>',
'<ul>',
'<li>Click the <b>Create</b> button to start wizard.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>General Step</b>',
'<ul>',
'<li>Enter <b>Name</b> (APEX component name).</li>',
unistr('<li>Select <b>Location \2192 Local Database</b>.</li>'),
unistr('<li>Select <b>Owner \2192 Parsing Schema</b>.</li>'),
'<li>Select the already created <b>Database Duality View</b> from dropdown list.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Click Next</b>',
'<ul>',
'<li>Move to <b>Data Profile</b> screen.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Review Data Profile</b>',
'<ul>',
'<li>Verify columns and datatypes.</li>',
'<li>Mark the correct column as <b>Primary Key</b> (usually ID).</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Click Create</b>',
'<ul>',
'<li>The Duality View will be saved in Shared Components.</li>',
'</ul>',
'</li>',
'',
'</ol>',
'',
'<p>',
'Note: Duality View must already exist in the database before registering it in Shared Components.',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
/
