wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7666718273793259313)
,p_plug_name=>'Data Profile Screen'
,p_static_id=>'data-profile-screen-2'
,p_parent_plug_id=>wwv_flow_imp.id(7664033587407908361)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!-- <p>',
'This screen appears while creating a JSON Source or Duality View.',
'Oracle APEX automatically analyzes the JSON structure and shows detected fields.',
'</p>',
'',
'<ol>',
'',
'<li>',
'<b>Position:</b>',
'<ul>',
'<li>Shows the order of the column in the JSON structure.</li>',
'<li>Helps identify column sequence.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Name:</b>',
'<ul>',
'<li>Displays the column name extracted from JSON data.</li>',
'<li>This becomes the attribute name used in APEX.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Data Type:</b>',
'<ul>',
'<li>Shows the detected data type (Number, Varchar2, JSON Document, etc.).</li>',
'<li>APEX automatically determines the data type.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Primary Key:</b>',
'<ul>',
'<li>Select the column that uniquely identifies each row.</li>',
'<li>Required to perform update, delete, and row-level operations.</li>',
'<li>Only one column (or proper unique identifier) should be selected.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Selector:</b>',
'<ul>',
'<li>Represents the JSON path used to extract the value.</li>',
'<li>Example: prefs.lang means data is inside the PROFILE JSON object.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Parent Column:</b>',
'<ul>',
'<li>Shows if the field belongs inside another JSON object.</li>',
'<li>Example: NAME inside PROFILE means PROFILE is parent object.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Actions Button:</b>',
'<ul>',
'<li>Used for additional configuration or refresh of profile.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Create Button:</b>',
'<ul>',
'<li>Finalizes and creates the JSON Source or Duality View.</li>',
'</ul>',
'</li>',
'',
'</ol>',
'',
'<p>',
'This screen is used to review and confirm the JSON structure before creating the source.',
'You must select the correct Primary Key to ensure proper data handling.',
'</p> -->',
'',
'',
'<ol>',
'',
'<li>',
'<b>Position:</b>',
'<ul>',
'<li>Shows the order of the detected JSON fields.</li>',
'<li>Controls how fields are arranged in the JSON Source.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Name:</b>',
'<ul>',
'<li>Displays the attribute name extracted from the JSON document.</li>',
'<li>This name is used in reports, forms, and SQL queries.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Data Type:</b>',
'<ul>',
'<li>Indicates the detected data type (Number, Varchar2, Date, JSON, etc.).</li>',
'<li>Used for validation and proper data handling.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Primary Key:</b>',
'<ul>',
'<li>Used to mark the column that uniquely identifies each record.</li>',
'<li>Required for update and delete operations.</li>',
'<li>Only one column (or valid unique column) should be selected.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Selector:</b>',
'<ul>',
'<li>Represents the JSON path used to extract the value from the JSON document.</li>',
'<li>Example: profile.name means the value comes from inside the profile object.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Parent Column:</b>',
'<ul>',
'<li>Used when the field belongs to a nested JSON object or array.</li>',
'<li>Defines parent-child relationship in JSON structure.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Actions Button:</b>',
'<ul>',
'<li>Provides additional configuration options.</li>',
'<li>Used to refresh or modify the detected profile.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Create Button:</b>',
'<ul>',
'<li>Finalizes and creates the JSON Source.</li>',
'<li>Saves the Data Profile configuration.</li>',
'</ul>',
'</li>',
'',
'</ol>',
'',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
