wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7666718469236259315)
,p_plug_name=>'JSON Sources - Interactive Report'
,p_static_id=>'json-sources-interactive-report-2'
,p_parent_plug_id=>wwv_flow_imp.id(7666718367723259314)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'',
'<li>',
'<b>Page Definition:</b>',
'<ul>',
'<li>Used to define basic page information.</li>',
'<li>Includes Page Name, Page Number, and Page Mode.</li>',
'<li>Controls how the page is created and identified in the application.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Data Source:</b>',
'<ul>',
'<li>Defines from where the page will fetch data.</li>',
'<li>Can be Table, View, JSON Source, REST Data Source, or Duality View.</li>',
'<li>APEX automatically generates regions and columns based on selected Data Source.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Navigation:</b>',
'<ul>',
'<li>Controls how the page appears in the application menu.</li>',
'<li>Allows adding the page to Navigation Menu or Navigation Bar.</li>',
'<li>Helps users access the page from the application menu.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Appearance (if available):</b>',
'<ul>',
'<li>Controls page template and layout settings.</li>',
'<li>Defines how the page looks in the application.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Next / Create Button:</b>',
'<ul>',
'<li>Moves to next step or creates the page.</li>',
'<li>Finalizes page creation process.</li>',
'</ul>',
'</li>',
'',
'</ol>',
'',
'<p>',
'These sections together define what the page will display, where the data comes from, and how users can navigate to it.',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
