,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
unistr('<li>Go to <b>Shared Components</b> \2192 Click <b>JSON Sources</b>.</li>'),
'',
'<li>Click the <b>Create</b> button.</li>',
'',
'<li>',
'On the General screen:',
'<ul>',
'<li>Enter the <b>Name</b>.</li>',
'<li>Select <b>JSON Source Type</b>.</li>',
'<li>Select the <b>Table with JSON Column</b>.</li>',
'</ul>',
'</li>',
'',
'<li>Click <b>Next</b>.</li>',
'',
unistr('<li>Select the <b>JSON Column</b> \2192 Click <b>Next</b>.</li>'),
'',
'<li>Select the <b>Primary Key</b> in Data Profile.</li>',
'',
'<li>Click <b>Create</b>.</li>',
'</ol>',
'',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
