wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7664033042970908356)
,p_plug_name=>'Use in Create JSON Source'
,p_static_id=>'use-in-create-json-source-2'
,p_parent_plug_id=>wwv_flow_imp.id(7664032909263908354)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!-- <ol>',
'',
'<li>',
'<b>Name:</b>',
'<ul>',
'<li>This is the name of the JSON Source inside the application.</li>',
'<li>It is used to identify the JSON Source in Shared Components.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>JSON Source Type:</b>',
'<ul>',
unistr('<li><b>Table with JSON Columns</b> \2013 Used when your database table contains a JSON column.</li>'),
unistr('<li><b>JSON Collection Table</b> \2013 Used when working with APEX JSON collections.</li>'),
'</ul>',
'</li>',
'',
'<li>',
'<b>Location:</b>',
'<ul>',
unistr('<li><b>Local Database</b> \2013 JSON table exists in the same database schema.</li>'),
unistr('<li><b>REST Enabled SQL Service</b> \2013 JSON table exists in a remote database.</li>'),
'</ul>',
'</li>',
'',
'<li>',
'<b>Owner:</b>',
'<ul>',
'<li>Specifies the schema that owns the JSON table.</li>',
'<li>Usually set to <b>Parsing Schema</b>.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Table with JSON Columns:</b>',
'<ul>',
'<li>Select the table that contains JSON data.</li>',
'<li>This table must have at least one column defined as JSON.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Next Button:</b>',
'<ul>',
'<li>Moves to the next step for column and data profile configuration.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Cancel Button:</b>',
'<ul>',
'<li>Closes the wizard without saving changes.</li>',
'</ul>',
'</li>',
'',
'</ol>',
'',
'<p>',
'This screen is used to register a database table containing JSON data as a JSON Source in Oracle APEX.',
'</p> -->',
'',
'<ol>',
'',
'<li>',
'<b>Name:</b>',
'<ul>',
'<li>Used to define the name of the JSON Source.</li>',
'<li>This name will be used later when selecting the source in regions or components.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>JSON Source Type:</b>',
'<ul>',
'<li>Determines where the JSON data comes from.</li>',
'<li>Example: Table with JSON Columns or JSON Collection Table.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Location:</b>',
'<ul>',
'<li>Specifies where the data is stored.</li>',
'<li>Local Database = Data is inside current schema.</li>',
'<li>REST Enabled SQL Service = Data comes from remote database.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Owner:</b>',
'<ul>',
'<li>Selects the database schema (Parsing Schema).</li>',
'<li>APEX uses this schema to access the table.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Table with JSON Columns:</b>',
'<ul>',
'<li>Select the table that contains JSON data.</li>',
'<li>APEX will scan this table to detect JSON columns.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Next Button:</b>',
'<ul>',
'<li>Moves to the next configuration step (JSON Columns screen).</li>',
'</ul>',
'</li>',
'',
'</ol>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
