wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7664033310918908358)
,p_plug_name=>'Use in JSON Columns'
,p_static_id=>'use-in-json-columns-2'
,p_parent_plug_id=>wwv_flow_imp.id(7664033182013908357)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!-- <ol>',
'',
'<li>',
'<b>JSON Column 1:</b>',
'<ul>',
'<li>Select the table column that contains JSON data.</li>',
'<li>The selected column must store valid JSON documents.</li>',
'<li>This column will be used as the main JSON source.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>JSON Schema for Column 1:</b>',
'<ul>',
'<li>Used to upload a JSON Schema file.</li>',
'<li>The schema defines the structure and validation rules of the JSON data.</li>',
'<li>Helps APEX understand the JSON format correctly.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Choose File Button:</b>',
'<ul>',
'<li>Allows uploading a JSON schema file (.json).</li>',
'<li>Optional but recommended for validation.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Next Button:</b>',
'<ul>',
'<li>Moves to the next step of configuration.</li>',
'<li>Used to continue JSON Source creation process.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Back Button:</b>',
'<ul>',
'<li>Returns to the previous step.</li>',
'</ul>',
'</li>',
'',
'</ol>',
'',
'<p>',
'This screen is used to select and configure the JSON column from a table so that Oracle APEX can properly read and manage JSON data.',
'</p> -->',
'',
'',
'<ol>',
'',
'<li>',
'<b>JSON Column:</b>',
'<ul>',
'<li>Select the column that contains JSON data.</li>',
'<li>This column must store valid JSON documents.</li>',
'<li>APEX reads this column to detect JSON structure.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>JSON Schema (Optional):</b>',
'<ul>',
'<li>Used to upload a JSON Schema file.</li>',
'<li>The schema defines the structure and validation rules of the JSON data.</li>',
'<li>Helps APEX correctly identify fields and data types.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Choose File Button:</b>',
'<ul>',
'<li>Allows you to upload a .json schema file.</li>',
'<li>Optional step for validation and structure control.</li>',
'</ul>',
'</li>',
'',
'<li>',
'<b>Next Button:</b>',
'<ul>',
'<li>Moves to the Data Profile screen.</li>',
'<li>APEX analyzes JSON data and detects fields automatically.</li>',
'</ul>',
'</li>',
'',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
