wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7666639315356105257)
,p_plug_name=>'Creating an Automation'
,p_static_id=>'creating-an-automation'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_grid_column_span=>6
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li><b>Create Automation</b>',
'        <ul>',
unistr('            <li>Go to <b>App Builder \2192 Application \2192 Shared Components \2192 Automations \2192 Create</b></li>'),
'            <li><b>Name:</b> Increase SAL</li>',
'            <li><b>Type:</b> Scheduled</li>',
'            <li><b>Actions Initiated On:</b> Query</li>',
'            <li><b>Schedule:</b> Custom',
'                <ul>',
'                    <li>Frequency: <b>Hourly</b></li>',
'                    <li>Interval: <b>2</b></li>',
'                    <li>Minute: <b>0</b></li>',
'                </ul>',
'            </li>',
unistr('            <li><b>Source:</b> Local Database \2192 Table \2192 EMP</li>'),
'            <li><b>Execute Actions When:</b> Rows returned</li>',
'            <li>Click <b>Create</b></li>',
'        </ul>',
'    </li>',
'    <li><b>Edit First Action (for SALESMAN with high commission)</b>',
'        <ul>',
'            <li>Edit <b>New Action</b></li>',
'            <li><b>Name:</b> Increase SAL for SALESMAN</li>',
'            <li><b>Code:</b>',
'                <ul>',
'                    <li><code>begin',
'                                update emp',
'                                set sal = round(sal * 1.015, 1)',
'                                where empno = :EMPNO;',
'',
'                                apex_automation.log_info(''SAL for '' || :ENAME || '' increased.'');',
'                              end;',
'                    </code></li>',
'                </ul>',
'            </li>',
'            <li><b>Condition (PL/SQL Expression):</b>',
'                <code>',
'                            :JOB = ''SALESMAN'' and :COMM > 500',
'                </code>',
'            </li>',
'            <li>Enable <b>Execute for Each Row</b></li>',
'            <li>Click <b>Apply Changes</b></li>',
'        </ul>',
'    </li>',
'    <li><b>Add Second Action (for others)</b>',
'        <ul>',
'            <li>Click <b>Add Action</b></li>',
'            <li><b>Name:</b> Increase SAL for all others</li>',
'            <li><code>begin',
'                        update emp',
'                        set sal = round(sal * 1.01, 1)',
'                        where empno = :EMPNO;',
'',
'                        apex_automation.log_info(''SAL for '' || :ENAME || '' increased by 1%.'');',
'                      end;',
'                </code>',
'            </li>',
'            <li><b>Condition:</b>',
'                <code>',
'                    :JOB != ''SALESMAN'' and (:COMM <= 500 or :COMM is null)',
'                </code>',
'            </li>',
'            <li>Enable <b>Execute for Each Row</b></li>',
'            <li>Click <b>Create</b></li>',
'        </ul>',
'    </li>',
'    <li><b>Run & Monitor</b>',
'        <ul>',
'            <li>Click <b>Save and Run</b></li>',
'            <li>Check <b>Execution Log</b> to review messages.</li>',
'            <li>Use <b>Purge Log</b> to clear logs if needed.</li>',
'            <li>You can verify updates in <b>SQL Workshop -> Object Browser.</b></li>',
'        </ul>',
'    </li>',
'    <li><b>Enable Weekly Schedule</b>',
'        <ul>',
'            <li>Open automation -> <b>Schedule Builder</b>',
'                <ul>',
'                    <li>Frequency: <b>Weekly</b></li>',
'                    <li>Days: <b>Mon-Fri</b></li>',
'                    <li>Time: <b>14:30</b></li>',
'                </ul>',
'            </li>',
'            <li>Set <b>Schedule Status:</b> Active</li>',
'            <li>Click <b>Save Changes</b></li>',
'        </ul>',
'    </li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
