wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7666639735440105261)
,p_plug_name=>'What is a Workflow in Oracle APEX?'
,p_static_id=>'what-is-a-workflow-in-oracle-apex'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>unistr('<p>A workflow in Oracle APEX is a structured sequence of steps\2014like approvals, tasks, or decisions\2014that automates your business processes. With workflows, your data flows between users, roles, and systems, seamlessly and securely.</p>')
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7666941168230821612)
,p_plug_name=>'Why Workflows Matter'
,p_static_id=>'why-workflows-matter'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Workflows in APEX bring value to your business by:</p>',
'<ul>',
'    <li>Automating Business Processes</li>Reduce turnaround time with built-in task routing, approvals, and DML operations.',
'    <li>Boosting Collaboration</li>Assign and track tasks dynamically based on user roles.',
'    <li>Tracking Progress in Real-Time</li>Monitor request status and performance with clear visibility.',
'    <li>Minimizing Manual Work</li>Trigger actions like email alerts, task completions, or updates-automatically.',
'</ul>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
