wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663990984564806135)
,p_plug_name=>'Globalization Page'
,p_static_id=>'globalization-page'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li><b>Application Primary Language:</b> Base language of the app. All translations and future changes must be made in this language.</li>',
'',
unistr('    <li><b>Application Language Derived From:</b> Determines how language is selected \2013 Static, Browser Language, or User Preference/Application Item.</li>'),
'',
unistr('    <li><b>Document Direction:</b> Sets layout direction \2013 Left-To-Right or Right-To-Left.</li>'),
'',
'    <li><b>Application Date Format:</b> Sets NLS_DATE_FORMAT for the session. Can use a fixed format or item reference. Defaults to DB setting if not specified.</li>',
'',
'    <li><b>Application Date Time Format:</b> Defines date-time format using substitution reference. Does not change NLS settings. Defaults to DB format if not set.</li>',
'',
'    <li><b>Application Timestamp Format:</b> Sets NLS_TIMESTAMP_FORMAT for the session. Supports fixed format or item reference.</li>',
'',
'    <li><b>Application Timestamp Time Zone Format:</b> Sets NLS_TIMESTAMP_TZ_FORMAT for the session. Supports fixed format or item reference.</li>',
'',
'    <li><b>Character Value Comparison:</b> Controls sorting rules (NLS_SORT) for SQL operations like ORDER BY and LIKE.</li>',
'',
'    <li><b>Character Value Comparison Behavior:</b> Controls NLS_COMP (Database Default, Binary, or Linguistic).</li>',
'',
'    <li><b>Automatic Time Zone:</b> Uses browser time zone for the session. Can be overridden using APEX_UTIL methods.</li>',
'',
'    <li><b>Automatic CSV Encoding:</b> Converts CSV output to a client-compatible character set to prevent corrupted multibyte data.</li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
