,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>In <b>Oracle APEX,</b> use the <b>Globalization</b> attributes to configure language and regional settings.</p>',
'<p>You can translate a single application to run in multiple languages and define:</p>',
'<ul>',
'    <li>Primary application language</li>',
'    <li>Default date, time, and timestamp formats</li>',
'    <li>Time zone format</li>',
'    <li>CSV encoding</li>',
'</ul>',
'<p>This allows the same application to support users in different languages concurrently.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
