wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663991170717806137)
,p_plug_name=>'Key Features and Benefits'
,p_static_id=>'key-features-and-benefits'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li><b>Globalization:</b> Automatically displays the correct message based on the user''s language settings, making applications multi-lingual.</li>',
'    <li><b>Centralized Management:</b> All messages are stored in one location ([Shared Components] > [Globalization] > [Text Messages]), allowing for easy updates across the entire application.</li>',
'    <li><b>Reusability:</b> Prevents repetitive coding for common messages like validation errors, help text, or confirmation dialogs.</li>',
'    <li><b>Substitution Values:</b> Messages can include placeholders (e.g., %0, %1 or named like %name) that are replaced dynamically at runtime, allowing for flexible message generation.</li>',
'    <li><b>Integration:</b> Usable on both the server-side (PL/SQL) and client-side (JavaScript).</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663991013369806136)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Oracle APEX <b>Text Messages</b> are <b>a powerful feature used to centralize, manage, and translate all text strings within an application,</b> supporting globalization and improving maintainability. They can be accessed from PL/SQL, JavaScript, '
||'and as Substitution Strings in various components.</p>',
'<p>To support additional languages not covered in the list, developers must provide their own translations. FOr example, if you develop a Bulgarian application and want to include report messages, such as pagination, in Bulgarian, you must translate '
||'the strings used in messages displayed in reports.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
/
