wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663991791909806143)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>'<p>Translating an Oracle APEX application <b>involves a structured process of exporting translatable text, modifying it, and re-importing it to create localized versions.</b> You typically map a primary language (e.g., English) to a target language, '
||'seed the application text into an XLIFF file, translate the content, upload the file, and publish the translation to generate a "shadow application" that APEX serves based on user language settings.</p>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
