,p_location=>null
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663993048683806156)
,p_plug_name=>'Publish the Application'
,p_static_id=>'publish-the-application'
,p_parent_plug_id=>wwv_flow_imp.id(7663991836801806144)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>130
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Publishing creates a copy of the base app with translated text for alternate languages.</p>',
'<p>Ensure globalization settings (e.g., browser language) match the translated language.</p>',
'<ol>',
unistr('    <li>Go to <b>App Builder</b> \2192 Select <b>Application \2192 Shared Components.</b></li>'),
'    <li>Under <b>Globalization,</b> click <b>Application Translations.</b></li>',
'    <li>Click <b>Publish Translated Applications.</b></li>',
'    <li>Select the required items.</li>',
'    <li>Click <b>Publish.</b></li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663992276745806148)
,p_plug_name=>'Seeding Translatable Text'
,p_static_id=>'seeding-translatable-text'
,p_parent_plug_id=>wwv_flow_imp.id(7663991836801806144)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Seeding copies all translatable text into the Translation Text repository and keeps it synced with the primary language app. Run it whenever the primary app changes.</p>',
'<ol>',
'    <li>Go to <b>App Builder</b> --> Select <b>Application</b> --> <b>Shared Components.</b></li>',
'    <li>Under <b>Globalization,</b> click <b>Application Translations.</b></li>',
'    <li>Click <b>Seed Translatable Text.</b></li>',
'    <li>Select the <b>target application.</b></li>',
'    <li>Click <b>Seed.</b></li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663992567923806151)
,p_plug_name=>'Translate the XLIFF File'
,p_static_id=>'translate-the-xliff-file'
,p_parent_plug_id=>wwv_flow_imp.id(7663991836801806144)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>70
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>After exporting the file in XLIFF format, you can translate it into the required language.</p>',
'<ul>',
'    <li>XLIFF is a standard XML format supported by most translation tools.</li>',
'    <li>APEX supports <b>UTF-8 encoded XLIFF files only</b> (both export and import).</li>',
'    <li>APEX allows <b>incremental translation,</b> so you can upload partially translated files.</li>',
'    <li>If any text is not translated, APEX automatically displays the <b>primary language</b> text instead.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7663992661186806152)
,p_plug_name=>'Uploading a Translated XLIFF Document'
,p_static_id=>'uploading-a-translated-xliff-document'
,p_parent_plug_id=>wwv_flow_imp.id(7663991836801806144)
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>90
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li>Go to <b>App Builder</b> --> Select <b>Application --> Shared Components.</b></li>',
'    <li>Under <b>Globalization,</b> click <b>Application Translations.</b></li>',
'    <li>Click <b>Apply XLIFF Translation Files.</b></li>',
'    <li>Click <b>Upload Files.</b></li>',
'    <li>Choose the file and click <b>Upload.</b></li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
