,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    e.id as card_id,',
'    e.first_name || '' '' || e.last_name  AS card_title,',
'    m.meeting_title as card_subtitle,',
'    m.status as card_badge,',
'    CASE',
'        WHEN m.status = ''Scheduled'' THEN ''u-info''   ',
'        WHEN m.status = ''Completed'' THEN ''u-success''   ',
'        WHEN m.status = ''Cancelled'' THEN ''u-danger''   ',
'        WHEN m.status = ''Pending'' THEN ''u-warning''   ',
'        ELSE ''u-color-23''',
'    END AS CARD_BADGE_CSS_CLASS,',
'    e.profile_photo as card_image,',
'    e.email_id as email,',
'    e.gender as gender,',
'    TO_CHAR(e.birth_date, ''DD-MON-YYYY'') as birth_date,',
'    m.meeting_type as meeting_type,',
'    TO_CHAR(m.start_datetime,''DD-MON-YYYY HH:MI AM'') as date_time,',
'    m.meeting_location as meeting_location,',
'    e.address as emp_address',
'from ta_emp e',
'join ta_meetings m',
'on e.id = m.organizer_id;'))
