,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4 style="text-decoration: underline"><strong> SQL Query </strong></h4>',
'<code>',
'SELECT',
'    AGE_GROUP,',
'    ROUND(AVG(COMPLETION_PCT),2) AS AVG_COMPLETION,',
'    SORT_ORDER',
'FROM (',
'    SELECT',
'        CASE',
'            WHEN AGE BETWEEN 18 AND 21 THEN ''18-21''',
'            WHEN AGE BETWEEN 22 AND 25 THEN ''22-25''',
'            WHEN AGE BETWEEN 26 AND 28 THEN ''26-28''',
'            WHEN AGE BETWEEN 29 AND 30 THEN ''29-30''',
'            ELSE ''30+''',
'        END AS AGE_GROUP,',
'        CASE',
'            WHEN AGE BETWEEN 18 AND 21 THEN 1',
'            WHEN AGE BETWEEN 22 AND 25 THEN 2',
'            WHEN AGE BETWEEN 26 AND 28 THEN 3',
'            WHEN AGE BETWEEN 29 AND 30 THEN 4',
'            ELSE 5',
'        END AS SORT_ORDER,',
'        COMPLETION_PCT',
'    FROM TA_EMP',
'    WHERE COMPLETION_PCT IS NOT NULL',
')',
'GROUP BY AGE_GROUP, SORT_ORDER',
'ORDER BY SORT_ORDER;',
'</code>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260630112933Z')
,p_updated_on=>wwv_flow_imp.dz('20260630113028Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
