 p_id=>wwv_flow_imp.id(13685613617027894746)
,p_name=>'Difference between Reports'
,p_static_id=>'difference-between-reports'
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    ''<b>'' || Feature || ''</b>'' as Feature,',
'    Classic_Report,',
'    Interactive_Report_IR,',
'    Interactive_Grid_IG,',
'    seq',
'from(',
'    SELECT ',
'        ''Main Purpose'' as Feature,',
'        ''Display data in a simple report'' as Classic_Report,',
'        ''Analyze data using built-in tools'' as Interactive_Report_IR,',
'        ''Manage and edit data directly'' as Interactive_Grid_IG,',
'        1 as seq',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Data Editing'',',
'        ''Read-only'',',
'        ''Read-only'',',
'        ''Supports inline editing'',',
'        2',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Searching'',',
'        ''Requires custom implementation'',',
'        ''Built-in search functionality'',',
'        ''Built-in search functionality'',',
'        3',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Filtering'',',
'        ''Requires custom implementation'',',
'        ''Built-in filtering options'',',
'        ''Built-in filtering options'',',
'        4',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Sorting'',',
'        ''Requires custom implementation'',',
'        ''Built-in sorting'',',
'        ''Built-in sorting'',',
'        5',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Column Management'',',
'        ''Fixed columns'',',
'        ''Users can show/hide and reorder columns'',',
'        ''Users can show/hide and reorder columns'',',
'        6',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Data Download'',',
'        ''Requires custom implementation'',',
'        ''Export to CSV, Excel, PDF, etc.'',',
'        ''Export to CSV, Excel, etc.'',',
'        7',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Row Operations'',',
'        ''Display only'',',
'        ''Display only'',',
'        ''Add, update, and delete rows'',',
'        8',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Customization by User'',',
'        ''Limited'',',
'        ''Users can save custom report layouts'',',
'        ''Users can save grid settings'',',
'        9',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Best Use Case'',',
'        ''Simple read-only reports'',',
'        ''Reports for data analysis'',',
'        ''Data entry and CRUD operations'',',
'        10',
'    FROM DUAL',
')',
'order by seq'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260701094717Z')
,p_updated_on=>wwv_flow_imp.dz('20260701094950Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
