 p_id=>wwv_flow_imp.id(7661418020615524640)
,p_name=>'Preview'
,p_static_id=>'preview'
,p_template=>4073835273271169698
,p_display_sequence=>60
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--horizontalBorders:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select (p.line_number - 1) AS SR_NO,',
'       p.col001 AS FIRST_NAME, ',
'       p.col002 AS LAST_NAME, ',
'       p.col003 AS EMAIL, ',
'       p.col004 AS PASSWORD, ',
'       p.col005 AS AGE, ',
'       p.col006 AS BIRTH_DATE, ',
'       p.col007 AS GENDER, ',
'       p.col008 AS CITY, ',
'       p.col009 AS COUNTRY, ',
'       p.col010 AS SKILLS, ',
'       p.col011 AS ADDRESS',
'       -- add more columns (col011 to col300) here.',
'  from apex_application_temp_files f, ',
'       table( apex_data_parser.parse(',
'                  p_content           => f.blob_content,',
'                  p_file_name         => f.filename,',
'                  p_xlsx_sheet_name   => case when :P100_XLSX_WORKSHEET is not null then :P100_XLSX_WORKSHEET end,',
'                  p_file_profile      => apex_data_loading.get_file_profile( p_static_id => ''employees'' ),',
'                  p_max_rows          => 100 ) ) p',
' where f.name = :P100_FILE',
' and p.line_number != 1'))
,p_display_when_condition=>'P100_FILE'
,p_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
