wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7635188151739790824)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Data Load Process'
,p_static_id=>'data-load-process'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_data BLOB;',
'    l_load_result apex_data_loading.t_data_load_result;',
'BEGIN',
'    SELECT blob_content',
'      INTO l_data',
'      FROM apex_application_temp_files',
'     WHERE name = :P100_FILE;',
'',
'INSERT INTO TA_EMP (',
'            FIRST_NAME,',
'            LAST_NAME,',
'            EMAIL_ID,',
'            PASSWORD_TXT,',
'            AGE,',
'            BIRTH_DATE,',
'            GENDER,',
'            CITY,',
'            COUNTRY,',
'            SKILLS,',
'            ADDRESS,',
'            ACTIVE_FLAG',
')',
'SELECT',
'            col001,                                               -- Customer  ',
'            col002,',
'            col003,',
'            col004,',
'            col005,',
'            col006,',
'            col007,',
'            col008,',
'            col009,',
'            col010,',
'            col011,',
'            ''Y''',
'    FROM TABLE(',
'        apex_data_parser.parse(',
'            p_content   => l_data,',
'            p_skip_rows => 1,',
'            p_file_type => apex_data_parser.c_file_type_xlsx',
'        )',
'    )',
'    WHERE NOT (',
'           col001 IS NULL',
'       AND col002 IS NULL',
'       AND col003 IS NULL',
'       AND col004 IS NULL',
'       AND col005 IS NULL',
'       AND col006 IS NULL',
'       AND col007 IS NULL',
'       AND col008 IS NULL',
'       AND col009 IS NULL',
'       AND col010 IS NULL',
'       AND col011 IS NULL',
'    );',
' ',
'    :P100_ERROR_ROW_COUNT := 0;',
'',
'END;',
'',
' '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(7661411506190524614)
,p_process_when_type=>'NEVER'
,p_process_success_message=>'Data Loaded.'
,p_internal_uid=>150743340513850713
);
