wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(7656204535700915547)
,p_name=>'Search Results'
,p_static_id=>'search-results'
,p_parent_plug_id=>wwv_flow_imp.id(7656204306468915544)
,p_template=>4073835273271169698
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight'
,p_new_grid_row=>false
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select m.MEETING_ID,',
'       m.MEETING_TITLE,',
'       m.MEETING_DESC,',
'       m.START_DATETIME,',
'       m.ORGANIZER_ID,',
'       m.END_DATETIME,',
'       e.FIRST_NAME || '' '' || e.LAST_NAME as Organizer_Name,',
'       e.AGE,',
'       m.MEETING_TYPE,',
'       case m.MEETING_TYPE',
'         when ''Online''    then ''t-Badge--warning''',
'         when ''Offline'' then ''t-Badge--info''',
'         else ''t-Badge--neutral''',
'    end as MEETING_TYPE_BADGE_STATE,',
'       m.MEETING_LOCATION,',
'       m.STATUS,',
'       case m.STATUS',
'         when ''Cancelled''  then ''t-Badge--danger''',
'         when ''Pending''    then ''t-Badge--warning''',
'         when ''Scheduled'' then ''t-Badge--info''',
'         when ''Completed'' then ''t-Badge--success''',
'         else ''t-Badge--neutral''',
'    end as STATUS_BADGE_STATE,',
'       m.CREATED_ON,',
'       m.CREATED_BY',
'  from TA_MEETINGS m',
'  left join TA_EMP e',
'  on m.ORGANIZER_ID = e.ID',
'  ORDER BY m.START_DATETIME'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'ROWS_X_TO_Y'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_updated_on=>wwv_flow_imp.dz('20260702065500Z')
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
