 p_id=>wwv_flow_imp.id(7656508180819452722)
,p_plug_name=>'Code'
,p_static_id=>'code'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>90
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4 style="text-decoration: underline"><strong>Add new button in Interactive Grid Report:</strong></h4>',
'<ol>',
'    <li>In <strong>Page Designer,</strong>select a <strong>region</strong></li>',
'    <li>Go to the <strong>Property Editor</strong></li>',
'    <li>Under the <strong>Region</strong> tab',
'        <ul>',
'            <li>Find <strong>Identification --> type,</strong>use <strong>Interactive Grid</strong></li>',
'            <li>Find <strong>Attributes --> Advanced,</strong>go to <strong>Initialization JavaScript Function</strong></li>',
'        </ul>',
'    </li>',
'</ol>',
'<code>',
'',
'function(config) {',
'    var $ = apex.jQuery,',
'        toolbarData = $.apex.interactiveGrid.copyDefaultToolbar();',
'    // remove unwanted groups',
'    toolbarData.toolbarRemove("reports");',
'    toolbarData.toolbarRemove("views");',
'    toolbarData.toolbarRemove("actions2");',
'    toolbarData.toolbarRemove("actions3");',
'    // Keep actions4 (right-most group)',
'    var rightGroup = toolbarData.toolbarFind("actions4");',
'    // Add custom button to right group',
'    rightGroup.controls.push({',
'        type: "BUTTON",',
'        label: "Tenant",',
'        icon: "fa fa-plus",',
'        iconBeforeLabel: true,',
'        hot: true,',
'        action: "open_dailog"',
'    });',
'    // Define action',
'    config.initActions = function(actions) {',
'        actions.add({',
'            name: "open_dailog",',
'            action: function() { $.event.trigger(''open_dailog''); }',
'        });',
'    };',
'    config.toolbarData = toolbarData;',
'    return config;',
'}',
'',
'</code>     ',
'',
'<ol>',
'    <p style="text-decoration: underline"><strong>Make One Custom Dynamic Action</strong></p>',
'    <li><strong>Name:</strong> open_dailog</li>',
'    <li><strong>Event:</strong> custom</li>',
'    <li><strong>custom_event:</strong> open_dailog</li>',
'    <li><strong>selection type:</strong> JavaScript</li>',
'    <li><strong>javaScript expression:</strong> document</li>',
'    <li><strong>Add True Action:</strong>',
'        <ul>',
'            <li><strong>Action:</strong> execute javascript code</li>',
'            <li><strong>Code:</strong> var purl = ''f?p=<span>&</span>APP_ID.:3:<span>&</span>APP_SESSION.'';   ',
'                                apex.navigation.redirect (purl);</li>',
'            <li>change page ID in code</li>',
'        </ul>',
'    </li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_updated_on=>wwv_flow_imp.dz('20260630125439Z')
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
