wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11682411531634073203)
,p_plug_name=>'Interactive Grid Features & Capabilities'
,p_static_id=>'interactive-grid-features-capabilities'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li><b>Inline Editing:</b>  Update, add, or delete data directly in the grid without navigating to a separate form or page. Changes are executed safely in a client-side model before saving.</li><br>',
'    <li><b>Data Manipulation:</b> Multi-select rows to execute bulk updates or deletions.</li><br>',
'    <li><b>Report Customization:</b> Rearrange data by dragging and dropping columns, resizing, freezing, hiding, or sorting.</li><br>',
'    <li><b>Aggregations & Grouping:</b> Quickly define sums, averages, or counts at the bottom of columns. Create control breaks to organize data visually.</li><br>',
'    <li><b>Built-in Charting:</b> Instantly visualize data with native charting functions.</li><br>',
'    <li><b>Multiple Views:</b> Toggle between the traditional Grid view, Single Row view (for form-like editing), Group By, and Pivot views.</li><br>',
'    <li><b>Data Export & Print:</b> Export your customized dataset to CSV, HTML, or directly print stylized PDFs while preserving layout.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260623104358Z')
,p_updated_on=>wwv_flow_imp.dz('20260630125519Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
