,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select MEETING_ID,',
'       MEETING_TITLE,',
'       MEETING_DESC,',
'       START_DATETIME,',
'       END_DATETIME,',
'       ORGANIZER_ID,',
