 p_id=>wwv_flow_imp.id(7657721062177011537)
,p_name=>'Employee and Meetings'
,p_static_id=>'employee-and-meetings'
,p_template=>4073835273271169698
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select m.MEETING_ID,',
'       m.MEETING_TITLE,',
'       m.MEETING_DESC,',
'       m.START_DATETIME,',
'       m.END_DATETIME,',
'       m.ORGANIZER_ID,',
'       m.MEETING_TYPE,',
'       m.MEETING_LOCATION,',
'       m.STATUS,',
'       case upper(m.STATUS)',
'         when ''CANCELLED''  then ''t-Badge--danger''',
'         when ''SCHEDULED''    then ''t-Badge--info''',
'         when ''COMPLETED'' then ''t-Badge--success''',
'         when ''PENDING'' then ''t-Badge--warning''',
'         else ''t-Badge--neutral''',
'    end as BADGE_STATE,',
'    case m.MEETING_TYPE',
'         when ''Online''    then ''t-Badge--success''',
'         when ''Offline'' then ''t-Badge--info''',
'         else ''t-Badge--neutral''',
'    end as MEETING_TYPE_BADGE_STATE,',
'       m.CREATED_ON,',
'       m.CREATED_BY,',
'       e.FIRST_NAME || '' '' || e.LAST_NAME as name,',
'       e.AGE,',
'       e.GENDER',
'  from TA_MEETINGS m',
'  left join TA_EMP e',
'  on m.organizer_id = e.id;'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
