,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.ID,',
'       t.PROJECT,',
'       t.TASK_NAME,',
'       t.START_DATE,',
'       t.END_DATE,',
'       t.STATUS,',
'       t.ASSIGNED_TO,',
'       p.project as PROJ_NAME,',
'       case t.STATUS',
'         when ''Closed'' then ''fa-check-circle-o''',
'         when ''Open''   then ''fa-exclamation-triangle-o''',
'         else ''fa-exclamation-circle-o''',
'       end as BADGE_ICON,',
'       case t.STATUS',
'         when ''Closed'' then ''success''',
'         when ''Open''   then ''danger''',
'         else ''warning''',
'       end as BADGE_COLOR',
'  from EBA_UT_CHART_TASKS t',
'  join EBA_UT_CHART_PROJECTS p',
'    on t.project = p.id',
' where t.STATUS <> ''Pending'';',
''))
