wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7657521280744860335)
,p_plug_name=>'Sample Query'
,p_static_id=>'sample-query'
,p_title=>'SQL Query'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<code>',
'SELECT',
'  CASE',
'    WHEN connect_by_isleaf = 1 THEN 0',
'    WHEN level = 1 THEN 1',
'    ELSE -1',
'  END AS status,',
'  level,',
'  task_name AS title,',
'  ''icon-tree-folder'' AS icon,',
'  id AS value,',
'  task_name AS tooltip,',
'  NULL AS link',
'FROM ta_tree',
'START WITH parent_task IS NULL',
'CONNECT BY PRIOR id = parent_task',
'ORDER SIBLINGS BY task_name;',
'</code>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
