wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(7658022536854305939)
,p_name=>'Meeting Details'
,p_static_id=>'meeting-details'
,p_template=>4073835273271169698
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select m.MEETING_ID,',
'       m.MEETING_TITLE,',
'       m.MEETING_DESC,',
'       to_char(m.START_DATETIME, ''DD-MON-YYYY HH:MI AM'') || '' - '' || to_char(m.END_DATETIME, ''DD-MON-YYYY HH:MI AM'') as DateTime,',
'       e.FIRST_NAME || '' '' || e.LAST_NAME as Organizer,',
'       e.EMAIL_ID,',
'       case upper(m.MEETING_TYPE)',
'            when ''ONLINE'' then',
'                 ''<span class="t-Badge t-Badge--success">',
'                    <span class="t-Icon fa fa-video-camera fa-anim-flash"></span>',
'                    Online',
'                  </span>''',
'            when ''OFFLINE'' then',
'                 ''<span class="t-Badge t-Badge--info">',
'                    <span class="t-Icon fa fa-building"></span>',
'                    Offline',
'                  </span>''',
'            else',
'                 ''<span class="t-Badge">'' || m.MEETING_TYPE || ''</span>''',
'       end as MEETING_TYPE,',
'       m.MEETING_LOCATION,',
'       case m.STATUS',
'            when ''Scheduled'' then',
'                 ''<span class="t-Badge t-Badge--info">Scheduled</span>''',
'            when ''Completed'' then',
'                 ''<span class="t-Badge t-Badge--success">Completed</span>''',
'            when ''Cancelled'' then',
'                 ''<span class="t-Badge t-Badge--danger">Cancelled</span>''',
'            when ''Pending'' then',
'                 ''<span class="t-Badge t-Badge--warning">Pending</span>''',
'            else',
'                 ''<span class="t-Badge">'' || m.STATUS || ''</span>''',
'       end as STATUS',
'  from TA_MEETINGS m ',
'  left join TA_EMP e',
'  on m.ORGANIZER_ID = e.ID'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'ROW_RANGES_WITH_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_updated_on=>wwv_flow_imp.dz('20260702060017Z')
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
