,p_location=>null
,p_region_image=>'https://g64cf2f956d7752-playground01.adb.us-ashburn-1.oraclecloudapps.com/ords/dev_tavish1/image/get?IMAGE_STATIC_ID=BREADCRUMB_ENTRY'
,p_region_image_attr=>'style="height:500px;"'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7657027750324981960)
,p_plug_name=>'Use of Breadcrumb'
,p_static_id=>'use-of-breadcrumb'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    <p>',
'        Breadcrumb Entry is used to define the navigation path of a specific page in the application.',
'        It helps users understand their current location and allows them to navigate easily to previous pages.',
'    </p>',
'',
'    <h4 style="text-decoration:underline">Purpose of Breadcrumb Entry</h4>',
'',
'    <ul>',
'        <li>To display the current page location.</li>',
'        <li>To create a navigation hierarchy.</li>',
'        <li>To allow users to move back to parent pages.</li>',
'        <li>To improve user experience and application navigation.</li>',
'    </ul>',
'',
'    <h4 style="text-decoration:underline">Fields Used in Breadcrumb Entry</h4>',
'',
'    <ol>',
'        <li>',
'            <strong>Page</strong><br>',
'            Select the page where the breadcrumb will be displayed.',
'        </li>',
'',
'        <li>',
'            <strong>Parent Entry</strong><br>',
'            Select the parent breadcrumb entry to define the navigation hierarchy.',
'        </li>',
'',
'        <li>',
'            <strong>Sequence</strong><br>',
'            Defines the display order of breadcrumb entries.',
'        </li>',
'',
'        <li>',
'            <strong>Short Name</strong><br>',
'            The text that appears in the breadcrumb navigation.',
'        </li>',
'',
'        <li>',
'            <strong>Long Name</strong><br>',
'            A detailed name of the breadcrumb entry.',
'        </li>',
'',
'        <li>',
'            <strong>Target</strong><br>',
'            Specifies where the breadcrumb link will navigate.',
'            <ul>',
'                <li>Page in this Application</li>',
'                <li>URL</li>',
'            </ul>',
'        </li>',
'',
'        <li>',
'            <strong>Conditions</strong><br>',
'            Defines when the breadcrumb should be displayed.',
'        </li>',
'',
'        <li>',
'            <strong>Authorization</strong><br>',
'            Controls which users can see the breadcrumb.',
'        </li>',
'',
'        <li>',
'            <strong>Build Option</strong><br>',
'            Used to enable or disable the breadcrumb during application build.',
'        </li>',
'    </ol>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
/
