,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select m.MEETING_ID,',
'       m.MEETING_TITLE as card_title,',
'       m.MEETING_DESC as card_text,',
'       m.START_DATETIME,',
'       m.END_DATETIME,',
'       m.ORGANIZER_ID,',
'       m.MEETING_TYPE as card_subtext,',
'       m.MEETING_LOCATION,',
'       m.STATUS as card_subtitle,',
'       m.CREATED_ON,',
'       m.CREATED_BY,',
'       substr(e.FIRST_NAME,1,1) || '''' || substr(e.LAST_NAME,1,1) as card_initials',
'  from TA_MEETINGS m',
'  left join TA_EMP e',
'  on m.ORGANIZER_ID = e.ID'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2976458789255810118
