 p_id=>wwv_flow_imp.id(7659065043885754013)
,p_plug_name=>'Advanced Formatting'
,p_static_id=>'advanced-formatting'
,p_parent_plug_id=>wwv_flow_imp.id(7659064928179754012)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'       m.MEETING_ID,',
'       m.MEETING_TITLE,',
'       m.MEETING_DESC,',
'',
'       to_char(m.START_DATETIME, ''MON'')      as MEETING_MONTH,',
'       to_char(m.START_DATETIME, ''DD'')       as MEETING_DAY,',
'       to_char(m.START_DATETIME, ''HH:MI AM'') as START_TIME,',
'       to_char(m.END_DATETIME,   ''HH:MI AM'') as END_TIME,',
'',
'       m.MEETING_TYPE,',
'       m.MEETING_LOCATION,',
'       m.STATUS,',
'       CASE UPPER(m.STATUS)',
'        WHEN ''SCHEDULED'' THEN ''fa-clock-o''',
'        WHEN ''COMPLETED'' THEN ''fa-check''',
'        WHEN ''CANCELLED'' THEN ''fa-remove''',
'        WHEN ''PENDING'' THEN ''fa-table-clock''',
'        ELSE ''fa-question-circle-o''',
