,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'       m.MEETING_ID,',
'       m.MEETING_TITLE,',
'       m.MEETING_DESC,',
'',
'       to_char(m.START_DATETIME, ''MON'')      as MEETING_MONTH,',
'       to_char(m.START_DATETIME, ''DD'')       as MEETING_DAY,',
'       to_char(m.START_DATETIME, ''HH:MI AM'') as START_TIME,',
'       to_char(m.END_DATETIME,   ''HH:MI AM'') as END_TIME,',
'',
'       m.MEETING_TYPE,',
'       m.MEETING_LOCATION,',
'       m.STATUS,',
'       CASE UPPER(m.STATUS)',
'        WHEN ''SCHEDULED'' THEN ''fa-clock-o''',
'        WHEN ''COMPLETED'' THEN ''fa-check''',
'        WHEN ''CANCELLED'' THEN ''fa-remove''',
'        ELSE ''fa-question-circle-o''',
'       END AS STATUS_ICON,',
'',
'       case m.STATUS',
'         when ''CANCELLED''  then ''u-color-10''',
'         when ''SCHEDULED''    then ''t-Badge--warning''',
'         when ''COMPLETED'' then ''t-Badge--success''',
'         else ''t-Badge--neutral''',
'    end as STATUS_BADGE_STATE,',
'',
'',
'       e.FIRST_NAME || '' '' || e.LAST_NAME as ORGANIZER_NAME,',
'       e.EMAIL_ID,',
'       e.AGE,',
'       e.GENDER,',
'       e.SKILLS,',
'       e.PROFILE_PHOTO,',
'       e.PHOTO_MIME',
'',
'from TA_MEETINGS m',
'left join TA_EMP e',
'  on m.ORGANIZER_ID = e.ID;',
''))
,p_plug_source_type=>'NATIVE_JQM_LIST_VIEW'
,p_plug_query_num_rows=>5
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'counter_column', 'MEETING_TYPE',
  'list_view_features', 'NESTED',
  'nested_list_column', 'AGE',
  'supplemental_info_column', 'MEETING_DESC',
  'text_column', 'MEETING_TITLE')).to_clob
,p_updated_on=>wwv_flow_imp.dz('20260715071013Z')
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
