 p_id=>wwv_flow_imp.id(7660171212712849916)
,p_name=>'Attribute Options'
,p_static_id=>'attribute-options'
,p_parent_plug_id=>wwv_flow_imp.id(7659729109692832959)
,p_template=>4073835273271169698
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--verticalBorders'
,p_grid_column_span=>5
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    ''Appearance'' AS ATTRIBUTES,',
'    ''Display'' AS OPTIONS,',
'    ''Multiple(Report)'' AS VALUE1',
'FROM DUAL',
'UNION ALL',
'SELECT ',
'    ''Settings''  AS ATTRIBUTES,',
'    ''Type''  AS OPTIONS,',
'    ''Image'' AS VALUE1',
'FROM DUAL',
'UNION ALL',
'SELECT ',
'    ''Settings''  AS ATTRIBUTES,',
'    ''Image''  AS OPTIONS,',
'    ''Select BLOB column'' AS VALUE1',
'FROM DUAL',
