,p_location=>null
,p_plug_source_type=>'NATIVE_DISPLAY_SELECTOR'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'display_region_icons', 'Y',
  'rds_mode', 'JUMP',
  'remember_selection', 'NO')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7660555754049699741)
,p_plug_name=>'Tips and Advanced Usage'
,p_static_id=>'tips-and-advanced-usage'
,p_icon_css_classes=>'fa-receipt'
,p_region_template_options=>'#DEFAULT#:t-Region--stacked:t-Region--scrollBody:margin-bottom-lg'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>50
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'    <li>',
'      <strong>Dynamic Control:</strong>',
'      You can use <em>JavaScript</em> and <em>Dynamic Actions</em> to control',
'      which tab is active programmatically on page load or based on',
'      other user interactions.',
'    </li>',
'',
'    <li>',
'      <strong>Static IDs:</strong>',
'      Assigning a <strong>Static ID</strong> to your regions is essential for',
'      advanced control, such as manipulating them with JavaScript or',
'      linking to a specific tab from another page.',
'    </li>',
'',
'    <li>',
'      <strong>Limitations:</strong>',
'      A page can generally only have one <em>Region Display Selector</em> region.',
'      For multiple tab sets on one page, a different approach using the',
'      <strong>Tabs Container</strong> region template with sub-regions',
'      is recommended.',
'    </li>',
'',
'    <li>',
'      <strong>Conditional Display:</strong>',
'      You can conditionally show or hide individual tabs by applying',
unistr('      conditions to their corresponding regions. If a region\2019s condition'),
'      returns <strong>false</strong>, its tab will not appear in the RDS.',
'    </li>',
'',
'  </ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
/
