 p_id=>wwv_flow_imp.id(13206391373187445919)
,p_chart_id=>wwv_flow_imp.id(13206391224942445918)
,p_static_id=>'new_1'
,p_seq=>10
,p_name=>'New'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    AGE_GROUP,',
'    ROUND(AVG(COMPLETION_PCT),2) AS AVG_COMPLETION,',
'    SORT_ORDER',
'FROM (',
'    SELECT',
'        CASE',
'            WHEN AGE BETWEEN 18 AND 21 THEN ''18-21''',
'            WHEN AGE BETWEEN 22 AND 25 THEN ''22-25''',
'            WHEN AGE BETWEEN 26 AND 28 THEN ''26-28''',
'            WHEN AGE BETWEEN 29 AND 30 THEN ''29-30''',
'            ELSE ''30+''',
'        END AS AGE_GROUP,',
'        CASE',
'            WHEN AGE BETWEEN 18 AND 21 THEN 1',
'            WHEN AGE BETWEEN 22 AND 25 THEN 2',
'            WHEN AGE BETWEEN 26 AND 28 THEN 3',
'            WHEN AGE BETWEEN 29 AND 30 THEN 4',
'            ELSE 5',
'        END AS SORT_ORDER,',
'        COMPLETION_PCT',
'    FROM TA_EMP',
'    WHERE COMPLETION_PCT IS NOT NULL',
')',
'GROUP BY AGE_GROUP, SORT_ORDER',
'ORDER BY SORT_ORDER;'))
,p_series_name_column_name=>'SORT_ORDER'
,p_items_value_column_name=>'AVG_COMPLETION'
,p_items_label_column_name=>'AGE_GROUP'
,p_line_style=>'solid'
