,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ''Total Employees'' AS LABEL,',
'    COUNT(*) VALUE,',
'    ''fa fa-users-alt'' AS ICON',
'FROM TA_EMP',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Total Meetings'' AS LABEL,',
'    COUNT(*) VALUE,',
'    ''fa fa-meeting-room'' AS ICON',
'FROM TA_MEETINGS',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Active Employees'' AS LABEL,',
'    COUNT(*) VALUE,',
'    ''fa fa-tasks-alt'' AS ICON',
'FROM TA_EMP',
'WHERE ACTIVE_FLAG = ''Y''',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Average Completion'' AS LABEL,',
'    ROUND(AVG(COMPLETION_PCT),2) VALUE,',
'    ''fa fa-ruler-combination'' AS ICON',
'FROM TA_EMP'))
