wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(13206393662495445942)
,p_plug_name=>'Recent Meetings Report'
,p_static_id=>'recent-meetings-report'
,p_parent_plug_id=>wwv_flow_imp.id(13685613143105894741)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>80
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select MEETING_ID,',
'       MEETING_TITLE,',
'       MEETING_DESC,',
'       START_DATETIME,',
'       END_DATETIME,',
'       ORGANIZER_ID,',
'       MEETING_TYPE,',
'       case MEETING_TYPE',
'         when ''Offline''    then ''t-Badge--warning''',
'         when ''Online'' then ''t-Badge--info''',
'         else ''t-Badge--neutral''',
'    end as MEETING_TYPE_BADGE_STATE,',
'       MEETING_LOCATION,',
'       STATUS,',
'       case STATUS',
'         when ''Cancelled''  then ''t-Badge--danger''',
'         when ''Pending''    then ''t-Badge--warning''',
'         when ''Scheduled'' then ''t-Badge--info''',
'         when ''Completed'' then ''t-Badge--success''',
'         else ''t-Badge--neutral''',
'    end as STATUS_BADGE_STATE,',
'       CREATED_ON,',
'       CREATED_BY,',
'       NULL AS ACTION',
'  from TA_MEETINGS'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
