wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7750675720793514305)
,p_plug_name=>'Configuration: Interactive Report'
,p_static_id=>'configuration-interactive-report'
,p_region_template_options=>'#DEFAULT#:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>This configuration demonstrates how to create menu-based row actions in an Interactive Report.</p>',
'<h3>Region</h3>',
'<p><b>Type:</b> Interactive Report</p>',
'<h3>Actions Column</h3>',
'<p>Add an additional column named <b>ROW_ACTION</b> of type <b>Actions</b> under Theme Components.</p>',
'<h4>Identification</h4>',
'<ul>',
'    <li><b>Type:</b> Actions</li>',
'</ul>',
'<p>This creates the Actions node under the column in Page Designer.</p>',
'<p>Right-click on the <b>Actions</b> node and select <b>Create Action.</b></p>',
'<h3>Action Configuration</h3>',
'<h4>Identification</h4>',
'<ul>',
'    <li><b>Position:</b> Actions</li>',
'    <li><b>Template:</b> Menu</li>',
'    <li><b>Label:</b>Actions (Enter the text to be displayed on the button)</li>',
'</ul>',
'<h4>Appearance</h4>',
'<ul>',
'    <li><b>Display Type:</b> Icon</li>',
'    <li><b>Icon:</b> fa-ellipsis-v-o</li>',
'</ul>',
'<p>Select the <b>Menus</b> node, right-click, and select <b>Create Menu.</b></p>',
'<h3>Menu Configuration</h3>',
'<h4>Identification</h4>',
'<ul>',
'    <li><b>Type:</b> Menu Entry</li>',
'    <li><b>Label:</b> Update</li>',
'</ul>',
'<h4>Behavior</h4>',
'<ul>',
'    <li><b>Type:</b> Select the action to be performed when the specified action type is clicked.</li>',
'</ul>',
'<p>Available Options</p>',
'<ul>',
'    <li>Redirect to Page in this Application</li>',
'    <li>Redirect to Page in a different Application</li>',
'    <li>Redirect to URL</li>',
'    <li>Trigger Action</li>',
'</ul>',
'<h4>Appearance</h4>',
'<ul>',
'    <li><b>Icon:</b> Enter the classes for the icon you want to add to the component.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260610102429Z')
,p_updated_on=>wwv_flow_imp.dz('20260610104017Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
