,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "ID",',
'       "FIRST_NAME",',
'       "LAST_NAME",',
'       "EMAIL_ID",',
'       "PASSWORD_TXT",',
'       "AGE",',
'       "COMPLETION_PCT",',
'       "BIRTH_DATE",',
'       "GENDER",',
'       "CITY",',
'       "COUNTRY",',
'       "TERMS_ACCEPTED",',
'       "SKILLS",',
'       "ADDRESS",',
'       "ACTIVE_FLAG",',
'       sys.dbms_lob.getlength( "PROFILE_PHOTO" ) "PROFILE_PHOTO",',
'       "PHOTO_MIME",',
'       sys.dbms_lob.getlength( "DOCUMENT_FILE" ) "DOCUMENT_FILE",',
'       "DOC_MIME",',
'       "CREATED_ON",',
'       "CREATED_BY",',
'       "UPDATED_ON",',
'       "UPDATED_BY",',
'       NULL AS ACTION',
'  from "TA_EMP"'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
