wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7750675921897514307)
,p_plug_name=>'Configuration: Interactive Report'
,p_static_id=>'configuration-interactive-report'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-expanded:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_grid_column_span=>3
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h3>Region</h3>',
'<p><b>Type:</b> Interactive Report</p>',
'<h3>Primary Key</h3>',
'<p>Define a Primary Key for the Interactive Report to uniquely identify each row. This is required for row selection to function correctly.</p>',
'<h3>Row Selector Column</h3>',
'<p>Right-click on the <b>Columns</b> node in Page Designer and select <b>"Create Row Selector".</b></p>',
'<p>This creates a column named <b>APEX$ROW_SELECTOR</b> with the type set to <b>Row Selector.</b></p>',
'<h4>Identification</h4>',
'<ul>',
'    <li><b>Type:</b> Row Selector</li>',
'</ul>',
'<h3>Row Selection</h3>',
'<ul>',
'    <li><b>Enable Multi Select:</b> Off (Single Row Selection)</li>',
'    <li><b>Hide Control:</b> Off</li>',
'    <li>A radio button is displayed for each row, allowing only one row to be selected at a time.</li>',
'    <li><b>Current Selection Page Item:</b> Specify a page item to store the selected row value.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260610103618Z')
,p_updated_on=>wwv_flow_imp.dz('20260610103910Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7750675877057514306)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Single Row Selection allows users to select exactly one record at a time within an Interactive Report in Oracle APEX.</p>',
'<p>When enabled, a radio button is displayed for each row, ensuring that only one row can be selected at any given time. This behavior is useful in scenarios where actions such as viewing details, editing records, or navigation should apply to a sing'
||'le row only.</p>',
'<p>The <b>Current Selection Page Item</b> is used to store the selection state. It holds the Primary Key value of the selected record, allowing it to be used in further processing or navigation.</p>',
'<p>This feature improves user experience by enforcing controlled selection and preventing multiple selections, making it ideal for detail-driven workflows.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260610103618Z')
,p_updated_on=>wwv_flow_imp.dz('20260610103618Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
