,p_navigation_bar_position=>'END'
,p_init_position_zoom_type=>'QUERY_RESULTS'
,p_layer_messages_position=>'BELOW'
,p_legend_position=>'END'
,p_bbox_type=>'SQL'
,p_bbox_sql_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select sdo_geometry( 2007,                                 -- 2D rectangle',
'                     4326,                                 -- longitude/latitude (WGS84)',
'                     null,                                 -- not used',
'                     sdo_elem_info_array( 1, 1003, 3 ),    -- rectangle definition',
'                     sdo_ordinate_array(',
'                         -106.6, 25.8,                     -- bottom-left (min_longitude, min_latitude)',
'                          -93.5, 36.5                      -- top-right   (max_longitude, max_latitude)',
'                     )',
'       )                   as geometry',
'  from sys.dual'))
,p_bbox_geometry_type=>'SDO_GEOMETRY'
,p_bbox_geometry_column=>'GEOMETRY'
,p_features=>'RECTANGLE_ZOOM:SCALE_BAR'
