wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7750676556361514313)
,p_plug_name=>'Overview'
,p_static_id=>'overview'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Maximum Rows to Display controls how many rows are shown to the user in an Interactive Report after all report processing is complete.</p>',
'',
'<p>This includes filters, sorting, control breaks, and other report settings. Even if more rows are available, only the specified number of rows will be displayed.</p>',
'',
'<p>This property works together with <b>Maximum Rows to Process</b>, which controls how many rows are retrieved before report processing begins.</p>',
'',
'<p>Example:</p>',
'<ul>',
'    <li>Total rows in table: <b>10,000</b></li>',
'    <li><b>Maximum Rows to Process:</b> 500</li>',
'    <li><b>Maximum Rows to Display:</b> 100</li>',
'</ul>',
'',
'<p>Behavior:</p>',
'<ul>',
'    <li>APEX retrieves <b>500 rows</b> from the database.</li>',
'    <li>Filters and sorting are applied on these 500 rows.</li>',
'    <li>After processing, only <b>100 rows</b> are displayed to the user.</li>',
'</ul>',
'<p>If matching data exists outside the processed rows, it will not be included in the final result.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260610111854Z')
,p_updated_on=>wwv_flow_imp.dz('20260610111854Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
