,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ID,',
'',
'    STOCK_CODE,',
'',
'    ''$'' || TO_CHAR(STOCK_PRICE,''999G999D00'') AS STOCK_PRICE,',
'',
'    COMPANY_NAME,',
'',
'    CASE',
'        WHEN STATUS = ''UP''',
unistr('        THEN ''\2191 '' || PRICE_CHANGE || ''%'''),
unistr('        ELSE ''\2193 '' || PRICE_CHANGE || ''%'''),
'    END AS PRICE_CHANGE,',
'',
'    CASE',
'        WHEN STATUS = ''UP''',
'        THEN ''success''',
'        ELSE ''danger''',
'    END AS COLOR_CLASS',
'',
'FROM TA_STOCK_METRICS',
''))
