'SELECT',
'    id,',
'    airport_name,',
'    city,',
'    state_name,',
'    airport_type,',
'    geometry,',
'',
'    CASE airport_type',
'        WHEN ''International'' THEN ''#2196F3''',
'        WHEN ''Domestic'' THEN ''#4CAF50''',
'        WHEN ''Military'' THEN ''#F44336''',
'        ELSE ''#9E9E9E''',
'    END AS color,',
'',
'    1 AS opacity,',
'',
'    CASE airport_type',
'        WHEN ''International'' THEN ''#0D47A1''',
'        WHEN ''Domestic'' THEN ''#1B5E20''',
'        WHEN ''Military'' THEN ''#B71C1C''',
'        ELSE ''#424242''',
