wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(9744945208477305734)
,p_name=>'Meeting'
,p_static_id=>'meeting'
,p_parent_plug_id=>wwv_flow_imp.id(9744945048896305732)
,p_template=>4073835273271169698
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select MEETING_ID,',
'       MEETING_TITLE,',
'       MEETING_DESC,',
'       START_DATETIME,',
'       END_DATETIME,',
'       ORGANIZER_ID,',
'       MEETING_TYPE,',
'       MEETING_LOCATION,',
'       STATUS,',
'       case STATUS',
'         when ''Cancelled''  then ''t-Badge--danger''',
'         when ''Scheduled''    then ''t-Badge--info''',
'         when ''Completed'' then ''t-Badge--success''',
'         when ''Pending'' then ''t-Badge--warning''',
'         else ''t-Badge--neutral''',
'    end as STATUS_BADGE_STATE,',
'    case MEETING_TYPE',
'         when ''Online''    then ''t-Badge--success''',
'         when ''Offline'' then ''t-Badge--info''',
'         else ''t-Badge--neutral''',
'    end as MEETING_TYPE_BADGE_STATE,',
'       CREATED_ON,',
'       CREATED_BY',
'  from TA_MEETINGS'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260617055126Z')
,p_updated_on=>wwv_flow_imp.dz('20260724123535Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
