wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11947513114374076109)
,p_plug_name=>'Available Controls in it'
,p_static_id=>'available-controls-in-it'
,p_parent_plug_id=>wwv_flow_imp.id(11947512901617076107)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Available controls include:</p>',
'<ul>',
'    <li><b>Report View -</b> Closes the Single Row View and returns to the grid.</li>',
'    <li><b>Change Menu -</b> Displays the options <b>Add Row, Duplicate Row, Delete Row, and Refresh Row.</b></li>',
'    <li><b>Setting Menu -</b> Enable or disable <b>Exclude Null Values and Display Values</b> settings.</b></li>',
'    <li><b>Previous and Next-</b> Click the <b>Previous and Next</b> buttons to navigate between rows in the grid.</b> settings.</b></li>',
'</ul>',
'<h4><b>Add Row</b></h4>',
'<p>Adds a new row below the current one.</p>',
'<h4><b>Duplicate Row</b></h4>',
'<p>Creates a copy of the currently selected row and inserts the copy below the original.</p>',
'<h4><b>Delete Row</b></h4>',
'<p>Deletes the current row.</p>',
'<h4><b>Refresh Row</b></h4>',
'<p>Reloads the row by calling the database and pulling in any updates.</p>',
'<h4><b>Revert Changes</b></h4>',
'<p>Undoes any changes to the row since the grid was last saved.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260624050202Z')
,p_updated_on=>wwv_flow_imp.dz('20260624054734Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
