wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11947513348752076111)
,p_plug_name=>'Interactive Grid Report Types'
,p_static_id=>'interactive-grid-report-types'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>110
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <p>',
'        Save your changes to an interactive grid by clicking Save As from the Actions, Report submenu.',
'    </p>',
'    <p>',
'        To save a private interactive grid report:',
'    </p>',
'    <ol>',
'        <li>',
'            Click the <strong>Actions</strong> menu and select <strong>Report</strong> then <strong>Save As</strong>.<br>',
'            The Save As dialog displays.',
'        </li>',
'        <li>',
'            In the Save As dialog:',
'            <ol type="a">',
'                <li>',
'                    Type - Select <strong>Private</strong>.',
'                </li>',
'                <li>',
'                    Name - Enter a name for the grid.',
'                </li>',
'            </ol>',
'        </li>',
'        <li>',
'            Click <strong>Save</strong>.',
'            <p>',
'                Save further changes to the report by selecting <strong>Save</strong> in the Actions, Report Setting submenu.',
'            </p>',
'        </li>',
'    </ol>',
'    <p>',
'        The report is saved and a confirmation message displays.',
'    </p>',
'</div>',
'<div>',
'    <h3>Renaming a Report in an Interactive Grid</h3>',
'    <p>',
'        Change the name of an interactive grid report by selecting Edit in the Actions, Report submenu.',
'    </p>',
'    <p>',
'        To rename a report:',
'    </p>',
'    <ol>',
'        <li>',
'            Select the report from the drop-down list.',
'        </li>',
'        <li>',
'            Click the <strong>Actions</strong> menu and select <strong>Report</strong> then <strong>Edit</strong>.<br>',
'            The Report Settings dialog displays.',
'        </li>',
'        <li>',
'            Rename the report.',
'        </li>',
'        <li>',
'            Click <strong>Save</strong>.',
'        </li>',
'    </ol>',
'    <p>',
'        The report is saved.',
'    </p>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260624052451Z')
,p_updated_on=>wwv_flow_imp.dz('20260624054734Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
