 p_id=>wwv_flow_imp.id(11947516423797076142)
,p_plug_name=>'Implementation'
,p_static_id=>'implementation'
,p_parent_plug_id=>wwv_flow_imp.id(11947516260555076140)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <ol>',
'        <li>',
'            Click the <strong>Actions</strong> menu and select <strong>Columns</strong>.<br>',
'            The Columns dialog displays.',
'        </li>',
'        <li>',
'            Edit the columns:',
'            <ul>',
'                <li>',
'                    <strong>Displayed</strong> - Select the check box to show a column in the grid; deselect a check box to hide a column in the grid.',
'                </li>',
'',
'                <li>',
'                    <strong>Move Up</strong> and <strong>Move Down</strong> - Adjust the order in which a column appears in the grid.',
'                </li>',
'',
'                <li>',
'                    <strong>Show</strong> button - Toggle whether the list displays <strong>All</strong>, <strong>Displayed</strong>, or <strong>Not Displayed</strong> (hidden) columns.',
'                </li>',
'',
'                <li>',
'                    <strong>Minimum Column Width (Pixel)</strong> - Adjust the displayed numeric value to widen or narrow the column.',
'                    <ol type="a">',
'                        <li>',
'                            Set the Minimum Column Width to a smaller number to narrow the column or a larger number to widen the column.',
'                        </li>',
'',
'                        <li>',
'                            If <strong>Stretch Column Widths</strong> is checked under <strong>Format</strong>, <strong>Actions</strong>, a column may display wider than its Minimum Column Width in order for the grid to stretch to the width of the re'
||'gion.</a>',
'                        </li>',
'                    </ol>',
'                </li>',
'            </ul>',
'        </li>',
'',
'        <li>',
'            Click <strong>Save</strong>.',
'        </li>',
'    </ol>',
'',
'    <p>',
'        The interactive grid refreshes.',
'    </p>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260624073118Z')
,p_updated_on=>wwv_flow_imp.dz('20260624073508Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
