 p_id=>wwv_flow_imp.id(11999616527391910022)
,p_plug_name=>'Editing a Filter'
,p_static_id=>'editing-a-filter'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <p>',
'        Edit a filter by clicking the name of a filter to open the Filters dialog. The Filters dialog enables you to edit properties of any filter.',
'    </p>',
'',
'    <p>',
'        To edit an existing filter:',
'    </p>',
'',
'    <ol>',
'        <li>',
'            Click the name of a filter.<br>',
'            The Filters dialog displays.',
'        </li>',
'',
'        <li>',
'            Edit the filter by selecting new values.',
'            <p>Editable parameters include:</p>',
'            <ul>',
'                <li>the filter type (row, column)</li>',
'                <li>the name of the row or column the filter applies to</li>',
'                <li>the filter operator</li>',
'                <li>the filtered value</li>',
'            </ul>',
'',
'            <p>',
'                Other filters can also be added, edited, enabled, and removed in this dialog.',
'            </p>',
'        </li>',
'',
'        <li>',
'            To add a new filter:',
'            <ol type="a">',
'                <li>',
'                    Click the <strong>Add</strong> button (+) adjacent to the Filters list.',
'                </li>',
'                <li>',
'                    Configure the appropriate fields.',
'                </li>',
'            </ol>',
'        </li>',
'',
'        <li>',
'            Click <strong>Save</strong> to apply your changes.',
'        </li>',
'    </ol>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260624075527Z')
,p_updated_on=>wwv_flow_imp.dz('20260624075641Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
