wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11999616701766910024)
,p_plug_name=>'Creating an Aggregation'
,p_static_id=>'creating-an-aggregation'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <p>',
'        Create an aggregation in an interactive grid by selecting Aggregate in the Actions, Data submenu.',
'    </p>',
'    <p>',
'        To create an aggregation against a column:',
'    </p>',
'    <ol>',
'        <li>',
'            Click the <strong>Actions</strong> menu, select <strong>Data</strong>, then <strong>Aggregate</strong>.',
'            <p>',
'                The Aggregation dialog appears. (Some fields may be pre-filled.)',
'            </p>',
'        </li>',
'        <li>',
'            In the Aggregation dialog:',
'            <ol type="a">',
'                <li>',
unistr('                    Column \2013 Select the column to define against'),
'                </li>',
'                <li>',
unistr('                    Aggregation \2013 Select the type of aggregation to apply'),
'                </li>',
'                <li>',
unistr('                    Tooltip \2013 (Optional) Add a label that appears when you hover the mouse over the aggregation.'),
'                </li>',
'                <li>',
unistr('                    (Optional) Show Overall Value \2013 Select to display the grand total of a column'),
'                </li>',
'            </ol>',
'        </li>',
'        <li>',
'            To add another aggregation:',
'            <ol type="a">',
'                <li>',
'                    Click the <strong>Add</strong> icon (+).',
'                    <p>',
'                        A new Aggregation appears in the list.',
'                    </p>',
'                </li>',
'                <li>',
'                    Define the new aggregation as described in the previous step.',
'                </li>',
'            </ol>',
'        </li>',
'        <li>',
'            Click <strong>Save</strong>.',
'        </li>',
'    </ol>',
'    <p>',
'        The result of the aggregation appears at the bottom of the last page of the report.',
'    </p>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260624085307Z')
,p_updated_on=>wwv_flow_imp.dz('20260624085307Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
