'<div>',
'    <p>',
'        Apply color highlighting to rows or columns in an interactive grid.',
'    </p>',
'    <ol>',
'        <li>',
unistr('            Click <strong>Actions</strong> \2192 <strong>Format</strong> \2192 <strong>Highlight</strong>.'),
'        </li>',
'        <li>',
'            Configure:',
'            <ol type="a">',
'                <li><strong>Name</strong> - Enter a highlight name.</li>',
'                <li><strong>Highlight</strong> - Select Row or Column.</li>',
'                <li><strong>Background Color</strong> - Choose a background color.</li>',
'                <li><strong>Text Color</strong> - Choose a text color.</li>',
'            </ol>',
'        </li>',
'        <li>',
'            (Optional) Add conditions:',
'            <ol type="a">',
'                <li><strong>Condition Type</strong> - Column.</li>',
'                <li><strong>Column</strong> - Select the column.</li>',
'                <li><strong>Operator</strong> - Select the condition.</li>',
'                <li><strong>Value</strong> - Enter or select the value.</li>',
'            </ol>',
'        </li>',
'        <li>',
unistr('            Use <strong>Add</strong> (+) to create more highlights or <strong>Delete</strong> (\2014) to remove one.'),
'        </li>',
'        <li>',
'            Click <strong>Save</strong>.',
'        </li>',
'    </ol>',
'</div>'))
