wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12027235545973551311)
,p_plug_name=>'Column Heading Menu in an Interactive Grid'
,p_static_id=>'column-heading-menu-in-an-interactive-grid'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <h4><strong>Sort Order Buttons</strong></h4>',
'    <p>',
'        The <strong>Sort Ascending</strong> and <strong>Sort Descending</strong> buttons appear at the right of every column heading.',
'    </p>',
'    <h4><strong>Column Heading Toolbar</strong></h4>',
'    <p>',
'        The Column Heading menu includes:',
'    </p>',
'    <ul>',
'        <li>',
'            <strong>Control Break</strong> - Creates a control break on the selected column.',
'        </li>',
'        <li>',
'            <strong>Aggregate</strong> - Creates an aggregation for the selected column.',
'        </li>',
'        <li>',
'            <strong>Freeze</strong> - Freezes the selected column during horizontal scrolling.',
'        </li>',
'        <li>',
'            <strong>Hide</strong> - Hides the selected column from view.',
'        </li>',
'    </ul>',
'    <h4><strong>Text Filter</strong></h4>',
'    <p>',
'        The text filter dynamically limits column values based on the text entered in the filter field.',
'    </p>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260624094849Z')
,p_updated_on=>wwv_flow_imp.dz('20260624101623Z')
