,p_plug_name=>'New'
,p_static_id=>'new'
,p_parent_plug_id=>wwv_flow_imp.id(12027235716166551313)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody:margin-top-sm'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <p>',
'        Creating a break group pulls the columns out of the interactive grid and displays them as a master record.',
'    </p>',
'    <p>',
'        To create a control break:',
'    </p>',
'    <ol>',
'        <li>',
'            Click the heading of the desired break group column.',
'        </li>',
'        <li>',
'            Click the <strong>Control Break</strong> icon.',
'        </li>',
'    </ol>',
'    <p>',
'        The interactive grid reloads with the control break applied, and a control break filter appears above the grid.',
'    </p>',
'    <p>',
'        To remove a control break, click the <strong>Remove Control Break</strong> icon (X) on the control break filter.',
'    </p>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260624101537Z')
,p_updated_on=>wwv_flow_imp.dz('20260624101915Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12027236202637551318)
,p_plug_name=>'New'
,p_static_id=>'new_1'
,p_parent_plug_id=>wwv_flow_imp.id(12027236021269551316)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody:margin-top-sm'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <p>',
'        To apply an aggregation against a selected column:',
'    </p>',
'    <ol>',
'        <li>',
'            Click the heading of the column to display the Column Heading menu.',
'        </li>',
'        <li>',
'            Click the <strong>Aggregate</strong> icon.<br>',
'            The Aggregation dialog appears.',
'        </li>',
'        <li>',
'            Configure the aggregation.',
'        </li>',
'        <li>',
'            Click <strong>Save</strong>.',
'        </li>',
'    </ol>',
'    <p>',
'        The interactive grid reloads with the aggregation applied.',
'    </p>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260624101537Z')
,p_updated_on=>wwv_flow_imp.dz('20260624101915Z')
