,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody:margin-top-sm'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <p>',
'        To freeze a column in place:',
'    </p>',
'    <ol>',
'        <li>',
'            Click the heading of the column you want to freeze.<br>',
'            The Column Heading menu appears.',
'        </li>',
'        <li>',
'            Click the <strong>Freeze</strong> icon.',
'        </li>',
'    </ol>',
'    <p>',
'        The scroll bar resizes to fit the new scrollable area.',
'    </p>',
'    <p>',
'        To unfreeze a column, open the Column Heading menu and click the <strong>Unfreeze</strong> icon (snowflake).',
'    </p>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260624101537Z')
,p_updated_on=>wwv_flow_imp.dz('20260624101915Z')
