,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <p>',
'        To hide a column in an interactive grid:',
'    </p>',
'    <ol>',
'        <li>',
'            Click the heading of the column to display the Column Heading menu.',
'        </li>',
'        <li>',
'            Click the <strong>Hide</strong> icon.',
'        </li>',
'    </ol>',
'    <p>',
'        The column is hidden and remaining columns shift to fill the space.',
'    </p>',
'    <p>',
'        To show a hidden column:',
'    </p>',
'    <ol start="3">',
'        <li>',
'            Click the <strong>Actions</strong> menu.',
'        </li>',
'        <li>',
'            Select <strong>Columns</strong>.',
'        </li>',
'        <li>',
'            Check the hidden column in the <strong>Displayed</strong> list.',
'        </li>',
'        <li>',
'            Click <strong>Save</strong>.',
'        </li>',
'    </ol>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
