 p_id=>wwv_flow_imp.id(12027238444785551340)
,p_plug_name=>'Supported Process Types'
,p_static_id=>'supported-process-types'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'    <ul>',
'        <li><strong>Clear Session State</strong> - Process to clear session state stored within Oracle APEX.</li>',
'        <li><strong>Close Dialog</strong> - Process to close the current modal or non-modal dialog page.</li>',
'        <li><strong>Data Loading</strong> - Process to load data into the target table or collection based on the given data load definition.</li>',
'        <li><strong>Execute Code</strong> - Executes PL/SQL code.</li>',
'        <li><strong>Execution Chain</strong> - Runs multiple processes in sequence.</li>',
'        <li><strong>Form - Automatic Row Processing (DML)</strong> - Inserts, updates, or deletes form data.</li>',
'        <li><strong>Form - Initialization</strong> - Initializes or fetches form data.</li>',
'        <li><strong>Human Task - Create</strong> - Process to create a human task, using an existing task definition from the application.</li>',
'        <li><strong>Human Task - Manage</strong> - Process to manage a human task. The different types of task management are Approve, Reject, Claim, Release, Delegate, Forward, Cancel, Comment and Invite Participant.</li>',
'        <li><strong>Interactive Grid - Automatic Row Processing (DML)</strong> - Inserts, updates, or deletes Interactive Grid rows.</li>',
'        <li><strong>Invoke API</strong> - Calls a database procedure/function or REST API.</li>',
'        <li><strong>Reset Pagination</strong> - Process to reset pagination of reports on the current page.</li>',
'        <li><strong>Send E-Mail</strong> - Sends emails with optional attachments.</li>',
'        <li><strong>Send Push Notification</strong> - Sends push notifications to users.</li>',
'        <li><strong>User Preferences</strong> - Saves user preference settings.</li>',
'        <li><strong>Web Service</strong> - Consumes a web service.</li>',
'    </ul>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260625050924Z')
,p_updated_on=>wwv_flow_imp.dz('20260625050924Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
