wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12027238689673551342)
,p_plug_name=>'Step-by-Step Instructions to create a Process'
,p_static_id=>'creating-page-processes'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'    <li><b>Open the Page Designer:</b>  Navigate to your application and open the desired page in the Oracle APEX Application Builder.</li><br>',
'    <li><b>Access the Processing Tab:</b>  In the left central pane, click on the <b>Processing</b> tab.</li><br>',
'    <li><b>Add a New Process:</b>  Locate the specific point where you want your logic to execute (e.g., Validating, Processing, or After Submit). Right-click the node and select Create Process.</li><br>',
'    <li><b>Name Your Process:</b>  In the Property Editor (right pane), provide a descriptive name under <b>Identification -> Name.</b></li><br>',
'    <li><b>Set the Process Type:</b>  Under <b>Identification -> Type,</b> select the kind of action you want to perform (e.g., <b>PL/SQL Code</b> to execute server-side logic, or <b>Invoke API</b> to interact with web services).</li><br>',
'    <li><b>Enter the Logic:</b>  Depending on the selected type, enter your PL/SQL code, SQL statement, or define the API action in the Code editor box.</li><br>',
'    <li><b>Configure Execution Options:</b>',
'        <ul>',
'            <li><b>Sequence:</b> Dictates the order in which multiple processes execute on your page.</li>',
'            <li><b>When Button Pressed:</b>  Specify a particular button (like a "Submit" or "Save" button) that triggers this specific process.</li>',
'        </ul>',
'    </li><br>',
'    <li><b>Save and Run:</b> Click Save in the upper right corner to apply your changes.</li><br>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260625052349Z')
,p_updated_on=>wwv_flow_imp.dz('20260625055901Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
