,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>An <b>Execution Chain</b> in Oracle APEX is <b>a powerful process type that allows developers to group and execute a sequence of child processes sequentially or in the background.</b> It offloads long-running tasks like data loading, API calls, or'
||' heavy file processing, keeping the user interface completely responsive.</p>',
'<h4>Steps</h4>',
'<ol>',
'    <li>Create Process -> <b>Execution Chain</b></li>',
'    <li>Add: Process 1 (Validate) --> Process 2 (Insert) --> Process 3 (Send Email) --> Process 4 (Clear Items)</li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
