wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12243386625017599701)
,p_plug_name=>'Human Task - Manage'
,p_static_id=>'human-task-manage'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>120
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>In Oracle APEX, <b>"Human Task - Manage"</b> is a <b>native page process type used to interact with and advance an existing task instance.</b></p>',
'<p>While <b>"Human Task - Create"</b> initiates a new task instance (like a leave request), the <b>"Human Task - Manage"</b> process updates, transitions, or completes that specific task based on a user''s action.</p>',
'<h4>Core Functions of Human Task - Manage</h4>',
'<ul>',
'    <li><b>Approve / Reject:</b> Completes the task and moves the overarching workflow forward.</li>',
'    <li><b>Claim / Release:</b> Sets ownership so a specific user can work on it, or puts it back into a shared queue.</li>',
'    <li><b>Delegate:</b> Forwards the task to another designated user.</li>',
'    <li><b>Request Info:</b> Asks the initiator or a participant to submit more information.</li>',
'</ul>',
'<h4>Steps</h4>',
'<ol>',
'    <li>Create Process = <b>Human Task Manage</b></li>',
'    <li>Choose = <b>Approve/Reject</b></li>',
'    <li>Pass --> <b>Task ID</b></li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260625084936Z')
,p_updated_on=>wwv_flow_imp.dz('20260625103228Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
