,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>User Preferences <b>allow developers to store application-specific settings for individual users (e.g., preferred theme, UI density, or default reports) without creating custom database tables.</b></p>',
'<h4>Steps</h4>',
'<ol>',
'    <li>Navigate to the <b>Processing</b> tab of your page.</li>',
'    <li>Right-click <b>Processes</b> and select <b>Create Process.</b></li>',
'    <li>Set the <b>Type</b> to <b>User Preferences.</b></li>',
'    <li>In the settings, choose to <b>Set Preference</b> or <b>Reset Preferences</b></li>',
'    <li>Define the execution point and sequence, then save the process.</li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
