,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ol>',
'  <li>Open <b>App Builder</b> and select your application.</li>',
'  <li>Open the required page in <b>Page Designer</b>.</li>',
'  <li>In the left pane, select the <b>Processing</b> tab.</li>',
'  <li>Right-click <b>Validations</b> and select <b>Create Validation</b>.</li>',
'  <li>Enter a descriptive <b>Name</b> for the validation.</li>',
'  <li>Set the <b>Sequence</b> to define the execution order.</li>',
'  <li>Select the <b>Validation Type</b> (for example, Item is NOT NULL, SQL Expression, PL/SQL Function, or PL/SQL Expression).</li>',
'  <li>If required, select the associated <b>Editable Region</b>.</li>',
'  <li>Set <b>Always Execute</b> to <b>On</b> or <b>Off</b> as needed.</li>',
'  <li>Enter the <b>Error Message</b> to display when the validation fails.</li>',
'  <li>Select the <b>Error Display Location</b> (Inline, Notification, or Error Page).</li>',
'  <li>Choose the <b>Associated Item</b> if the error should appear next to a specific page item.</li>',
'  <li>Click <b>Save</b> to create the validation.</li>',
'</ol>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
