'select (p.line_number - 1) AS SR_NO,',
'       p.col001 AS FIRST_NAME, ',
'       p.col002 AS LAST_NAME, ',
'       p.col003 AS EMAIL, ',
'       p.col004 AS PASSWORD, ',
'       p.col005 AS AGE, ',
'       p.col006 AS BIRTH_DATE, ',
'       p.col007 AS GENDER, ',
'       p.col008 AS CITY, ',
'       p.col009 AS COUNTRY, ',
'       p.col010 AS SKILLS, ',
'       p.col011 AS ADDRESS',
'       -- add more columns (col011 to col300) here.',
'  from apex_application_temp_files f, ',
'       table( apex_data_parser.parse(',
'                  p_content           => f.blob_content,',
'                  p_file_name         => f.filename,',
'                  p_xlsx_sheet_name   => case when :P223_XLSX_WORKSHEET is not null then :P223_XLSX_WORKSHEET end,',
'                  p_file_profile      => apex_data_loading.get_file_profile( p_static_id => ''employees'' ),',
'                  p_max_rows          => 100 ) ) p',
' where f.name = :P223_FILE',
' and p.line_number != 1'))
