wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(13127927046718505233)
,p_plug_name=>'Create Page-Level Computations'
,p_static_id=>'create-page-level-computations'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4>Step 1: Create the Computation</h4>',
'<ol>',
'    <li>Open your page in <b>Page Designer</b>.</li>',
'    <li>Go to the <b>Left Pane</b> (Application Navigator).</li>',
'    <li>Choose your execution phase based on when the calculation should happen:',
'        <ul>',
'            <li><b>To display a value on load:</b> Click the <b>Rendering</b> tab (leftmost icon), right-click <b>Pre-Rendering</b>, and select <b>Create Computation.</b></li>',
'            <li><b>To calculate a value on submit:</b> Click the <b>Processing</b> tab (third icon), right-click <b>Processing,</b>, and select <b>Create Computation.</b></li>',
'        </ul>',
'    </li>',
'</ol>',
'<h4>Step 2: Set Identification and Execution</h4>',
'<p>Click on your new computation and configure the <b>Property Editor</b> (Right Pane):</p>',
'<ul>',
'    <li><b>Idntification > Name:</b> Give it a descriptive name (e.g., Calculate Total).</li>',
'    <li><b>Identification > Item Name:</b> Select the exact page item you want to populate (e.g., P1_TOTAL).</li>',
'    <li><b>Execution > Sequence:</b> Set the order number. Lower numbers run first.</li>',
'    <li><b>Execution > Point:</b> : Confirm it is assigned to the correct phase (e.g., Before Header for page load, or After Submit for form submission).</li>',
'</ul>',
'<h4>Step 3: Define the Source Logic</h4>',
'<p>Scroll down to the <b>Computation</b> section in the Right Pane and choose your preferred type:</p>',
'<p><b>Option A: PL/SQL Expression (Best for simple formulas)</b></p>',
'<ul>',
'    <li><b>Type:</b> PL/SQL Expression</li>',
'    <li><b>Value:</b> :APP_USER</li>',
'    <li><b>Point:</b> Before Header</li>',
'</ul>',
'<h4>Step 5: Save</h4>',
'<p>Click the <b>Save</b> or <b>Save and Run</b> button at the top right of the Page Designer interface.</p>'))
,p_plug_header=>'<p>To set up a page-level computation, you need to define the target item, choose when it runs, and specify the logic.</p>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260629062409Z')
,p_updated_on=>wwv_flow_imp.dz('20260629095204Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(13127928683413505249)
,p_plug_name=>'Execution Points'
,p_static_id=>'execution-points'
,p_region_template_options=>'#DEFAULT#:t-Region--hideShowIconsMath:is-collapsed:t-Region--scrollBody'
,p_plug_template=>2665811232373458102
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h4>1) New Session</h4>',
'<p>Only <b>once</b>, when a <b>new APEX session</b> is created.</p>',
'<p><b>Use case:</b> ',
'<ul>',
'    <li>Initialize application values.</li>',
'    <li>Initialize application values.</li>',
'    <li>Generate session-specific data.</li>',
'</ul>',
'<h4>2) Before Header</h4>',
'<p>Before any HTML of the page is generated.</p>',
'<p><b>Use case:</b> ',
'<ul>',
'    <li>Set default values.</li>',
'    <li>Fetch data from the database.</li>',
'    <li>Calculate values before the page is shown.</li>',
'</ul>',
'<h4>3) After Header</h4>',
'<p>After the page header is generated but before the regions.</p>',
'<p><b>Use case:</b> ',
'<ul>',
'    <li>Values that depend on the header.</li>',
'    <li>Rarely used.</li>',
'</ul>',
'<h4>4) Before Regions</h4>',
'<p>Immediately before page regions are rendered.</p>',
'<p><b>Use case:</b> ',
'<ul>',
'    <li>Calculate values used inside reports.</li>',
'    <li>Prepare data for charts or interactive reports.</li>',
'</ul>',
'<h4>5) After Regions</h4>',
'<p>After all regions are rendered but before the footer.</p>',
'<p><b>Use case:</b> ',
'<ul>',
'    <li>Logging</li>',
'    <li>Statistics</li>',
'    <li>Final page calculations</li>',
'</ul>',
'<h4>6) Before Footer</h4>',
'<p>Immediately before the page footer.</p>',
'<h4>7) After Footer</h4>',
'<p>After the footer has been processed.</p>',
'<h4>8) After Submit</h4>',
'<p>After the user clicks a Submit button.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260629100355Z')
,p_updated_on=>wwv_flow_imp.dz('20260629100451Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
