,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
unistr('    <li><b>Generate Text With AI</b> \2013 Generates content using AI based on the provided prompt or context.'),
'',
unistr('    <li><b>Show AI Assistant</b> \2013 Opens the built-in AI Assistant for user interaction.'),
'',
unistr('    <li><b>Clear</b> \2013 Clears the value of one or more page items.'),
'',
unistr('    <li><b>Close Region</b> \2013 Closes a collapsible region.'),
'',
unistr('    <li><b>Collapse Tree</b> \2013 Collapses all expanded nodes in a Tree region.'),
'',
unistr('    <li><b>Disable</b> \2013 Makes an item or button read-only and unavailable for interaction.'),
'',
unistr('    <li><b>Enable</b> \2013 Makes a disabled item or button available again.'),
'',
unistr('    <li><b>Expand Tree</b> \2013 Expands nodes in a Tree region.'),
'',
unistr('    <li><b>Hide</b> \2013 Hides items, buttons, or regions.'),
'',
unistr('    <li><b>Open Region</b> \2013 Opens an expandable or collapsible region.'),
'',
unistr('    <li><b>Refresh</b> \2013 Reloads a region or item without refreshing the entire page.'),
'',
unistr('    <li><b>Set Focus</b> \2013 Moves the cursor to a specific page item.'),
'',
unistr('    <li><b>Set Value</b> \2013 Sets the value of an item using SQL, PL/SQL, JavaScript, or a static value.'),
'',
unistr('    <li><b>Show</b> \2013 Displays hidden items, buttons, or regions.'),
'',
unistr('    <li><b>Trigger Geocoding</b> \2013 Converts an address into latitude and longitude coordinates.'),
'</ul>',
'',
'<h4>Execute Actions</h4>',
'',
'<ul>',
unistr('    <li><b>Download</b> \2013 Downloads a file generated by the application.'),
'',
unistr('    <li><b>Execute JavaScript Code</b> \2013 Runs custom JavaScript code in the browser.'),
'',
unistr('    <li><b>Execute Server-side Code</b> \2013 Executes PL/SQL code on the server using AJAX.'),
'',
unistr('    <li><b>Invoke Interactive Report Dialog</b> \2013 Opens an Interactive Report dialog such as Filter or Actions.'),
'',
unistr('    <li><b>Print Report</b> \2013 Opens the print view of a report.'),
'</ul>',
'',
'<h4>Miscellaneous</h4>',
'',
'<ul>',
unistr('    <li><b>Cancel Event</b> \2013 Stops the current browser event from continuing.'),
'',
unistr('    <li><b>Get Current Position</b> \2013 Retrieves the user''s current geographic location.'),
'',
unistr('    <li><b>Share</b> \2013 Opens the browser''s native sharing dialog (supported browsers).'),
'</ul>',
'',
'<h4>Navigation</h4>',
'',
'<ul>',
unistr('    <li><b>Cancel Dialog</b> \2013 Closes a dialog without saving changes.'),
'',
unistr('    <li><b>Close Dialog</b> \2013 Closes the current dialog page.'),
'',
unistr('    <li><b>Submit Page</b> \2013 Submits the current page to execute validations, computations, and processes.'),
'</ul>',
'',
'<h4>Notification</h4>',
'',
'<ul>',
unistr('    <li><b>Alert</b> \2013 Displays a simple alert message.'),
'',
unistr('    <li><b>Clear Errors</b> \2013 Removes all current validation or error messages.'),
'',
unistr('    <li><b>Confirm</b> \2013 Displays a confirmation dialog with OK and Cancel options.'),
'',
unistr('    <li><b>Show Error Message</b> \2013 Displays a custom error message on the page.'),
'',
unistr('    <li><b>Show Success Message</b> \2013 Displays a success notification.'),
'</ul>',
'',
'<h4>Style</h4>',
'',
'<ul>',
unistr('    <li><b>Add Class</b> \2013 Adds a CSS class to a component.'),
'',
unistr('    <li><b>Remove Class</b> \2013 Removes a CSS class from a component.'),
'',
unistr('    <li><b>Set Style</b> \2013 Applies CSS style properties directly to a component.'),
'</ul>'))
