wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13477378059993485650)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Add Data In Collection'
,p_static_id=>'add-data-in-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   rec APEX_COLLECTIONS%ROWTYPE;',
'   l_seq_id NUMBER;',
'BEGIN',
'   IF :P240_SEQ_ID IS NULL THEN',
'      APEX_COLLECTION.ADD_MEMBER(',
'         p_collection_name => ''EMP_DETAILS'',',
'         p_c001 => :P240_FIRST_NAME,',
'         p_c002 => :P240_LAST_NAME,',
'         p_c003 => :P240_EMAIL_ID,',
'         p_c004 => :P240_BIRTH_DATE,',
'         p_c005 => :P240_GENDER',
'      );',
'',
'      SELECT MAX(seq_id) INTO l_seq_id',
'      FROM apex_collections',
'      WHERE collection_name = ''EMP_DETAILS'';',
'',
'      :P240_SEQ_ID := l_seq_id;',
'   ELSE',
'      SELECT * INTO rec FROM APEX_COLLECTIONS',
'      WHERE collection_name = ''EMP_DETAILS''',
'        AND seq_id = :P240_SEQ_ID;',
'',
'      APEX_COLLECTION.UPDATE_MEMBER(',
'         p_collection_name => ''EMP_DETAILS'',',
'         p_seq => :P240_SEQ_ID,',
'         p_c001 => :P240_FIRST_NAME,',
'         p_c002 => :P240_LAST_NAME,',
'         p_c003 => :P240_EMAIL_ID,',
'         p_c004 => :P240_BIRTH_DATE,',
'         p_c005 => :P240_GENDER,',
'         p_c006 => rec.c006,',
'         p_c007 => rec.c007,',
'         p_c008 => rec.c008,',
'         p_c009 => rec.c009,',
'         p_c010 => rec.c010,',
'         p_c011 => rec.c011,',
'         p_c012 => rec.c012,',
'         p_c013 => rec.c013,',
'         p_c014 => rec.c014,',
'         p_c015 => rec.c015',
'      );',
'   END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(13473341611125385320)
,p_internal_uid=>13477378059993485650
,p_created_on=>wwv_flow_imp.dz('20260701070957Z')
,p_updated_on=>wwv_flow_imp.dz('20260702073729Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
