wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13477377924431485649)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Collection'
,p_static_id=>'create-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   -- Create collection if it does not exist',
'   IF NOT APEX_COLLECTION.COLLECTION_EXISTS(''EMP_DETAILS'') THEN',
'      APEX_COLLECTION.CREATE_COLLECTION(''EMP_DETAILS'');',
'   END IF;',
'',
'   -- Fetch data from collection',
'   BEGIN',
'      SELECT c001,',
'             c002,',
'             c003,',
'             c004,',
'             c005',
'        INTO :P240_FIRST_NAME,',
'             :P240_LAST_NAME,',
'             :P240_EMAIL_ID,',
'             :P240_BIRTH_DATE,',
'             :P240_GENDER',
'        FROM APEX_COLLECTIONS',
'       WHERE COLLECTION_NAME = ''EMP_DETAILS''',
'         AND SEQ_ID = :P240_SEQ_ID;',
'',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'         :P240_FIRST_NAME := NULL;',
