 p_id=>wwv_flow_imp.id(13723545618629243002)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Page Item Value Using Collection'
,p_static_id=>'set-page-item-value-using-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   IF APEX_COLLECTION.COLLECTION_EXISTS(''EMP_DETAILS'') THEN',
'      FOR rec IN (',
'         SELECT * FROM APEX_COLLECTIONS',
'         WHERE COLLECTION_NAME = ''EMP_DETAILS'' AND SEQ_ID = :P241_SEQ_ID',
'      ) LOOP',
'         :P241_CITY := rec.c006;',
'         :P241_COUNTRY := rec.c007;',
'         :P241_ADDRESS := rec.c008;',
'      END LOOP;',
'   END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>13723545618629243002
,p_created_on=>wwv_flow_imp.dz('20260701073100Z')
,p_updated_on=>wwv_flow_imp.dz('20260701073100Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13723545778219243003)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Member In Collection'
,p_static_id=>'update-member-in-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   rec APEX_COLLECTIONS%ROWTYPE;',
'BEGIN',
'    SELECT * INTO rec',
'   FROM APEX_COLLECTIONS',
'   WHERE COLLECTION_NAME = ''EMP_DETAILS''',
'     AND SEQ_ID = :P241_SEQ_ID;',
'',
'   APEX_COLLECTION.UPDATE_MEMBER(',
'      p_collection_name => ''EMP_DETAILS'',',
'      p_seq             => :P241_SEQ_ID,',
'      p_c001            => rec.c001,',
'      p_c002            => rec.c002,',
'      p_c003            => rec.c003,',
'      p_c004            => rec.c004,',
'      p_c005            => rec.c005,',
'      p_c006            => :P241_CITY,',
'      p_c007            => :P241_COUNTRY,',
'      p_c008            => :P241_ADDRESS,',
'      p_c009            => rec.c009,',
'      p_c010            => rec.c010,',
'      p_c011            => rec.c011,',
'      p_c012            => rec.c012,',
'      p_c013            => rec.c013,',
'      p_c014            => rec.c014,',
'      p_c015            => rec.c015',
'   );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>13723545778219243003
,p_created_on=>wwv_flow_imp.dz('20260701073334Z')
,p_updated_on=>wwv_flow_imp.dz('20260701102228Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
