wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13723546310770243009)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Page Item Value Using Collection'
,p_static_id=>'set-page-item-value-using-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   IF APEX_COLLECTION.COLLECTION_EXISTS(''EMP_DETAILS'') THEN',
'      FOR rec IN (',
'         SELECT * FROM APEX_COLLECTIONS',
'         WHERE COLLECTION_NAME = ''EMP_DETAILS'' AND SEQ_ID = :P242_SEQ_ID',
'      ) LOOP',
'         :P242_MEETING_TITLE := rec.c009;',
'         :P242_MEETING_DESC := rec.c010;',
'         :P242_MEETING_LOCATION := rec.c011;',
'         :P242_START_DATETIME := rec.c012;',
'         :P242_END_DATETIME := rec.c013;',
'         :P242_MEETING_TYPE := rec.c014;',
'         :P242_STATUS := rec.c015;',
'      END LOOP;',
'   END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>13723546310770243009
,p_created_on=>wwv_flow_imp.dz('20260701101333Z')
,p_updated_on=>wwv_flow_imp.dz('20260701101531Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13723546408477243010)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Member In Collection'
,p_static_id=>'update-member-in-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   rec APEX_COLLECTIONS%ROWTYPE;',
'BEGIN',
'    SELECT * INTO rec',
'   FROM APEX_COLLECTIONS',
'   WHERE COLLECTION_NAME = ''EMP_DETAILS''',
'     AND SEQ_ID = :P242_SEQ_ID;',
'',
'   APEX_COLLECTION.UPDATE_MEMBER(',
'      p_collection_name => ''EMP_DETAILS'',',
'      p_seq             => :P242_SEQ_ID,',
'      p_c001            => rec.c001,',
'      p_c002            => rec.c002,',
'      p_c003            => rec.c003,',
'      p_c004            => rec.c004,',
'      p_c005            => rec.c005,',
'      p_c006            => rec.c006,',
'      p_c007            => rec.c007,',
'      p_c008            => rec.c008,',
'      p_c009            => :P242_MEETING_TITLE,',
'      p_c010            => :P242_MEETING_DESC,',
'      p_c011            => :P242_MEETING_LOCATION,',
'      p_c012            => :P242_START_DATETIME,',
'      p_c013            => :P242_END_DATETIME,',
'      p_c014            => :P242_MEETING_TYPE,',
'      p_c015            => :P242_STATUS',
'   );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>13723546408477243010
,p_created_on=>wwv_flow_imp.dz('20260701101516Z')
,p_updated_on=>wwv_flow_imp.dz('20260701102242Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
