wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13723546629843243012)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert Data Into Table'
,p_static_id=>'insert-data-into-table'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_emp_id number;',
'BEGIN',
'',
'    INSERT INTO TA_EMP(',
'        FIRST_NAME,',
'        LAST_NAME,',
'        EMAIL_ID,',
'        PASSWORD_TXT,',
'        AGE,',
'        COMPLETION_PCT,',
'        BIRTH_DATE,',
'        GENDER,',
'        CITY,',
'        COUNTRY,',
'        TERMS_ACCEPTED,',
'        ADDRESS,',
'        ACTIVE_FLAG',
'    ) VALUES (',
'        :P243_FIRST_NAME,',
'        :P243_LAST_NAME,',
'        :P243_EMAIL_ID,',
'        123,',
'        :P243_AGE,',
'        3,',
'        TO_DATE(:P243_BIRTH_DATE,''DD-MON-YYYY''),',
'        :P243_GENDER,',
'        :P243_CITY,',
'        :P243_COUNTRY,',
'        ''Y'',',
'        :P243_ADDRESS,',
'        ''Y''',
'    ) ',
'',
'    RETURNING ID INTO v_emp_id;',
'',
'    INSERT INTO TA_MEETINGS(',
'        MEETING_TITLE,',
'        MEETING_DESC,',
'        START_DATETIME,',
'        END_DATETIME,',
'        ORGANIZER_ID,',
'        MEETING_TYPE,',
'        MEETING_LOCATION,',
'        STATUS',
'    ) VALUES(',
'        :P243_MEETING_TITLE,',
'        :P243_MEETING_DESC,',
'        TO_TIMESTAMP(:P243_START_DATETIME,''DD-MON-YYYY HH:MIPM''),',
'        TO_TIMESTAMP(:P243_END_DATETIME,''DD-MON-YYYY HH:MIPM''),',
'        v_emp_id,',
'        :P243_MEETING_TYPE,',
'        :P243_MEETING_LOCATION,',
'        :P243_STATUS',
'    );',
'',
'    APEX_COLLECTION.DELETE_COLLECTION(''EMP_DETAILS'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(13473355723404385345)
,p_process_success_message=>'Data Inserted Successfully !'
,p_internal_uid=>13723546629843243012
,p_created_on=>wwv_flow_imp.dz('20260701102503Z')
,p_updated_on=>wwv_flow_imp.dz('20260701111529Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13723546574414243011)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Page Item Value Using Collection'
,p_static_id=>'set-page-item-value-using-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   IF APEX_COLLECTION.COLLECTION_EXISTS(''EMP_DETAILS'') THEN',
'      FOR rec IN (',
'         SELECT * FROM APEX_COLLECTIONS',
'         WHERE COLLECTION_NAME = ''EMP_DETAILS'' AND SEQ_ID = :P243_SEQ_ID',
'      ) LOOP',
'         :P243_FIRST_NAME := rec.c001;',
'         :P243_LAST_NAME := rec.c002;',
'         :P243_EMAIL_ID := rec.c003;',
'         :P243_BIRTH_DATE := rec.c004;',
'         :P243_GENDER := rec.c005;',
'         :P243_CITY := rec.c006;',
'         :P243_COUNTRY := rec.c007;',
'         :P243_ADDRESS := rec.c008;',
'         :P243_MEETING_TITLE := rec.c009;',
'         :P243_MEETING_DESC := rec.c010;',
'         :P243_MEETING_LOCATION := rec.c011;',
'         :P243_START_DATETIME := rec.c012;',
'         :P243_END_DATETIME := rec.c013;',
'         :P243_MEETING_TYPE := rec.c014;',
'         :P243_STATUS := rec.c015;',
'      END LOOP;',
'   END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>13723546574414243011
,p_created_on=>wwv_flow_imp.dz('20260701101934Z')
,p_updated_on=>wwv_flow_imp.dz('20260701105918Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
