 p_id=>wwv_flow_imp.id(7659600435430546646)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT DATA'
,p_static_id=>'insert-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_EMP_ID NUMBER;',
'BEGIN',
'    INSERT INTO TA_EMP (',
'        FIRST_NAME,',
'        LAST_NAME,',
'        EMAIL_ID,',
'        AGE,',
'        BIRTH_DATE,',
'        GENDER,',
'        CITY,',
'        COUNTRY,',
'        ADDRESS',
'    ) VALUES (',
'        :P977_FIRST_NAME,',
'        :P977_LAST_NAME,',
'        :P977_EMAIL_ID,',
'        TO_NUMBER(:P977_AGE),  ',
'        -- TO_DATE(:P977_BIRTH_DATE, ''MM/DD/YYYY''), ',
'        TO_DATE(:P977_BIRTH_DATE, ''DD-MON-YYYY''), ',
'        :P977_GENDER,',
'        :P977_CITY,',
'        :P977_COUNTRY,',
'        :P977_ADDRESS',
'    )',
'    RETURNING ID INTO V_EMP_ID;',
'',
'    INSERT INTO TA_MEETINGS(',
'        MEETING_TITLE,',
'        MEETING_DESC,',
'        START_DATETIME,',
'        END_DATETIME,',
'        ORGANIZER_ID,',
'        MEETING_TYPE,',
'        MEETING_LOCATION,',
'        STATUS',
'    ) VALUES (',
'        :P977_MEETING_TITLE,',
'        :P977_MEETING_DESC,',
'        TO_TIMESTAMP(:P977_START_DATETIME,''DD-MON-YYYY HH:MI AM''), ',
'        TO_TIMESTAMP(:P977_END_DATETIME,''DD-MON-YYYY HH:MI AM''),',
'        V_EMP_ID,',
'        :P977_MEETING_TYPE,',
'        :P977_MEETING_LOCATION,',
'        ''Pending''',
'    );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(7659600557240546647)
,p_internal_uid=>175155624204606535
,p_updated_on=>wwv_flow_imp.dz('20260724130350Z')
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
